    servePinsRevision: false,
    /** How many times the page read the list. */
    pinReads: 0,
    /** Every pin write, as `{method, id, body}`, in order. */
    pinCalls: [],
    /** `{status, error, detail}` for the pin writes to answer with instead, or null. */
    pinFailure: null,
    /** The same for the list read. */
    pinListFailure: null,
