test("every number this page is tuned by stays inside a band that says what would be wrong", () => {
  for (const [name, [low, high, why]] of Object.entries(TUNING_BANDS)) {
    const value = sourceConstant(name);
    assert.ok(
      value >= low && value <= high,
      `${name} is ${value}, outside ${low}..${high}: ${why}`
    );
  }
  // The two that are a RELATION rather than a range. A default outside the offered range is a
  // width the reader cannot get back to once they have moved the handle.
  assert.ok(
    sourceConstant("MIN_READING_CH") < sourceConstant("MAX_READING_CH"),
    "the narrowest column the reader may choose is not narrower than the widest"
  );
  assert.ok(
    sourceConstant("DEFAULT_READING_CH") >= sourceConstant("MIN_READING_CH") &&
      sourceConstant("DEFAULT_READING_CH") <= sourceConstant("MAX_READING_CH"),
    "the default reading width is not one the reader is allowed to choose"
  );
});

test("...and the table covers EVERY constant, so a new one cannot escape by being new", () => {
  // This is the part that generalises. Pinning the constants that happened to be noticed leaves
  // the next one unpinned, and the next one is exactly where the same defect comes back.
  const declared = [...PAGE_CODE.matchAll(/^const ([A-Z][A-Z0-9_]*) = (\d+);$/gm)].map(
    (m) => m[1]
  );
  assert.ok(declared.length >= 13, `only ${declared.length} constants found — the scan is broken`);
  const unpinned = declared.filter((name) => !(name in TUNING_BANDS));
  assert.deepStrictEqual(
    unpinned,
    [],
    `the page tunes itself by ${unpinned.join(", ")} and nothing here says what value of ` +
      "them would be wrong, so widening one of them is a change no test can see"
  );
  const gone = Object.keys(TUNING_BANDS).filter((name) => !declared.includes(name));
  assert.deepStrictEqual(gone, [], `the table pins ${gone.join(", ")}, which no longer exist`);
});

/** The fold control on a rendered message, or undefined when it has none. */
const foldButton = (li) => li.descendants().find((node) => node.className === "fold");

/** The reply control on a rendered channel message. `#51 reply-view`. */
const replyButton = (li) => li.descendants().find((node) => node.className === "reply-button");

/**
 * `#410 inline-reply-editor`. Whether the reply's box is open in the stream: on the main screen, in a
 * list's place for it (#column-reply or #side-reply), as Reply opens it on every list of the channel.
 */
const replyInStream = (page) => page.screen() === "main" &&
  ["column-reply", "side-reply"].some((id) => page.el("reply-compose").parentNode === page.el(id) && !page.el(id).hidden);

/** One buffer of microphone audio arriving from the browser's audio graph. */
function speakInto(page) {
  const processor = page.processors[page.processors.length - 1];
  assert.ok(processor && processor.onaudioprocess, "nothing is capturing the microphone");
  processor.onaudioprocess({
    inputBuffer: { getChannelData: () => new Float32Array(4096) },
  });
}

/** The words a seam puts ON THE SCREEN — not the ones it keeps inside its disclosure. */
const seamLabel = (li) =>
  li.descendants().find((node) => node.className === "seam-label").textContent;

/** The sentences a seam keeps INSIDE its disclosure. */
const seamDetail = (li) =>
  li.descendants().find((node) => node.className === "seam-detail").textContent;

/** How many words a piece of interface text spends. */
const words = (text) => text.trim().split(/\s+/).filter(Boolean).length;

/**
 * The band a seam's disclosure has to stay inside.
 *
 * A CEILING, because the first version of the seam printed four sentences onto the transcript and
 * the fix that moved them into a disclosure did not shorten them — sixty words one tap away is
 * still sixty words, and nobody opens them.
 *
 * A FLOOR, because the assertion this replaces was `length > 120` and that floor was the whole
 * reason it existed: without one, deleting the explanation outright passes.
 */
// RAISED from 10 by `#74 scroll-test-strength`, finding 2: the shortest disclosure the page ships
// is eighteen words, so a floor of ten let every one of them be cut to half its length with both
// seam tests still green. Fifteen is under that shortest one with a little room to edit, and over
// the point where a disclosure stops being able to say both of the things these seams have to say
// — what happened, and what it means for the agent's memory.
//
// "The shortest the page ships" was a claim about `SEAM_DETAILS.failed`, which NO TEST MEASURED
// when the floor was raised on the strength of it — the three sites driven below reach three other
// strings. "EVERY WORDING A SEAM CAN SHOW" is what makes it a measured fact: it walks both tables
// and pins the distance between this floor and the real shortest, so the justification cannot
// quietly stop being true of the page.
const SEAM_DETAIL_MIN_WORDS = 15;
const SEAM_DETAIL_MAX_WORDS = 28;

/**
 * One of web/voice.js's tables of interface sentences, read out of the source.
 *
 * The page composes them with `+` across several lines, so this joins the string literals inside
 * each entry. Deliberately strict about the shape: a table it cannot parse is an assertion
 * failure, never an empty result that measures nothing.
 */
function sourceStringTable(name) {
  const found = new RegExp(`const ${name} = \\{([\\s\\S]*?)\\n\\};`).exec(PAGE_CODE);
  assert.ok(found, `the page's code (web/voice.js, web/src/) no longer states a ${name}`);
  const table = {};
  for (const part of found[1].split(/\n {2}(?=[\w"]+:)/)) {
    const key = /^\s*"?([\w-]+)"?:/.exec(part);
    if (!key) {
      continue;
    }
    const pieces = [...part.matchAll(/"((?:[^"\\]|\\.)*)"/g)].map((m) => m[1]);
    assert.ok(pieces.length, `${name}.${key[1]} is not a string this test can read`);
    table[key[1]] = pieces.join("");
  }
  assert.ok(Object.keys(table).length, `${name} parsed as an empty table, so it measures nothing`);
  return table;
}

/** The one status line's machine-readable state, which is what colours its dot. */
const state = (page) => page.el("status-line").getAttribute("data-state");

/**
 * What the channel view says about itself, at the head of the list.
 *
 * `#63 status-line-placement` moved this off the status strip: it is a standing fact about what
 * you are looking at, and the strip is a message that takes itself away after a few seconds.
 */
const channelSummaryText = (page) => {
  const [line] = page.el("channel-summary").children;
  assert.ok(line, "the channel view states no summary at all");
  assert.equal(line.className, "seam", "the summary is not drawn in the seam idiom");
  return seamLabel(line);
};

/** Just the audio frames, not the initiation message or a pong. */
const audioFrames = (socket) => socket.sent.filter((s) => s.includes("user_audio_chunk"));

/** Sign in and land on the main screen, without placing a call. */
async function signIn(page) {
  page.el("api-token").value = "write-token-aaaaaaaaaaaaaaaa";
  await page.el("save-token").click();
  await page.settle();
  assert.equal(page.screen(), "main", "signing in did not reach the main interface");
}

// --- the page's own names, and the browser's (`#624 voice-page-modularity`) ----------------------

/**
 * The browser's globals, as the pinned TypeScript's DOM declarations name them (every `declare var`,
 * `function`, `const` and `let` in lib.dom.d.ts), and the ones the page's browsers have that those
 * declarations do not yet: `navigation`, the Navigation API (Chromium), which `historyIndex` reads.
 */
const DOM_GLOBALS = new Set([...readFileSync(join(WEB, "..", "contract", "node_modules", "typescript", "lib", "lib.dom.d.ts"),
  "utf8").matchAll(/^declare (?:var|function|const|let) (\w+)/gm)].map((found) => found[1]).concat(["navigation"]));

test("`#624 voice-page-modularity`: no top-level name of the legacy script or its prelude hides a browser global", () => {
  // A classic script's top-level function or var becomes a property of `window`, over the
  // browser's own: a `function navigation()` in voice.js replaced the Navigation API that
  // `historyIndex` reads `window.navigation` for, which only a real browser showed. The prelude's
  // constants hide a global from every unqualified reference in the page as surely.
  const ts = loadTool("typescript");
  const file = ts.createSourceFile("voice.js", SCRIPT, ts.ScriptTarget.Latest, true, ts.ScriptKind.JS);
  const names = new Set(PRELUDE ? PRELUDE.names : []);
  for (const statement of file.statements) {
    if ((ts.isFunctionDeclaration(statement) || ts.isClassDeclaration(statement)) && statement.name) names.add(statement.name.text);
    if (ts.isVariableStatement(statement)) {
      for (const declaration of statement.declarationList.declarations) {
        if (ts.isIdentifier(declaration.name)) names.add(declaration.name.text);
      }
    }
  }
  assert.ok(names.size > 1000 && DOM_GLOBALS.size > 500 && DOM_GLOBALS.has("navigation") && names.has("selectedChannelId"),
    "the scan found too few names to mean anything");
  // `stop` (the call's teardown) has hidden `window.stop` for as long as the page has had calls, and
  // nothing in the page means the browser's; it is the one name allowed, and only it.
  const KNOWN = new Set(["stop"]);
  const hiding = [...names].filter((name) => DOM_GLOBALS.has(name) && !KNOWN.has(name));
  assert.deepStrictEqual(hiding, [], `these page names hide the browser's globals of the same name: ${hiding.join(", ")}`);
  for (const name of KNOWN) assert.ok(names.has(name), `${name} no longer needs its exception: take it off the list`);
});

// --- the selection's owner (`#624 voice-page-modularity`) ----------------------------------------

test("`#624 voice-page-modularity`: the selection starts on no channel, and every choice reaches every subscriber in order, read-only", () => {
  const navigation = NAVIGATION.createNavigation();
  assert.deepStrictEqual(navigation.snapshot(), { channelId: "" });
  const heard = [];
  navigation.subscribe((snapshot) => heard.push(["first", snapshot.channelId]));
  const stop = navigation.subscribe((snapshot) => heard.push(["second", snapshot.channelId]));
  navigation.selectChannel("200");
  navigation.selectChannel("200");
  stop();
  navigation.selectChannel("300");
  assert.deepStrictEqual(heard, [["first", "200"], ["second", "200"], ["first", "200"], ["second", "200"], ["first", "300"]],
    "a choice of the channel already chosen must still redraw what shows it");
  const snapshot = navigation.snapshot();
  assert.equal(snapshot.channelId, "300");
  assert.throws(() => { "use strict"; snapshot.channelId = "400"; }, TypeError, "a snapshot could be written to");
  assert.equal(navigation.snapshot().channelId, "300");
});

test("`#624 voice-page-modularity`: the bar's picker shows the selection, and a value put on it with no change chooses nothing", async () => {
  const other = { id: "1110000000000000002", label: "build noise", writable: false };
  const page = newPage();
  page.channels = [{ ...CHANNEL }, other];
  await signIn(page);
  await showDiscord(page, [message({ content: "hello" })]);
  assert.equal(page.el("discord-channel").value, CHANNEL.id);
  // A value with no change event, which no reader can make in a browser: the selection stays.
  page.el("discord-channel").value = other.id;
  assert.equal(page.pure("selectedChannelId()"), CHANNEL.id);
  // The reader's choice, with its change: the selection first, then the picker shows it.
  await page.el("discord-channel").dispatch("change");
  await page.settle();
  assert.equal(page.pure("selectedChannelId()"), other.id);
  // A channel the picker does not list, as a link can name, chooses none, as a <select> does.
  page.pure("(chooseChannel('9990000000000000009'), 0)");
  assert.deepStrictEqual([page.pure("selectedChannelId()"), page.el("discord-channel").value], ["", ""]);
});

test("`#624 voice-page-modularity`: the token is kept, read and forgotten on its own handle, and a refusing device says so the way the page relies on", () => {
  const kept = new Map();
  const storage = { getItem: (key) => kept.get(key) ?? null, setItem: (key, value) => kept.set(key, value), removeItem: (key) => kept.delete(key) };
  const credentials = SETTINGS.createCredentials(storage);
  assert.equal(credentials.token(), "", "no token reads as none");
  assert.equal(credentials.signedOutByRename(), false);
  kept.set("gent-talk.token", "old-token-aaaaaaaaaaaa");
  assert.equal(credentials.signedOutByRename(), true, "a token under the old name is a sign-out by the rename");
  credentials.keep("write-token-aaaaaaaaaaaaaaaa");
  assert.deepStrictEqual([credentials.token(), kept.get("vibe-talk.token"), credentials.signedOutByRename()],
    ["write-token-aaaaaaaaaaaaaaaa", "write-token-aaaaaaaaaaaaaaaa", false]);
  credentials.forget();
  assert.deepStrictEqual([credentials.token(), kept.has("vibe-talk.token")], ["", false]);
  // Storage turned off: reading the token throws, as the page's callers expect; the sign-in path's
  // question does not.
  const refused = () => { throw new Error("SecurityError"); };
  const off = SETTINGS.createCredentials({ getItem: refused, setItem: refused, removeItem: refused });
  assert.throws(() => off.token(), /SecurityError/);
  assert.throws(() => off.keep("x"), /SecurityError/);
  assert.equal(off.signedOutByRename(), false);
});

test("`#624 voice-page-modularity`: the settings sync runs on its own ports: the first read, the seed, a local change pushed, a refusal kept local", async () => {
  const KEY = "vibe-talk.voice.read-mode";
  const kept = new Map([[KEY, "hide"], ["vibe-talk.voice.combine", "1"]]);
  const storage = { getItem: (k) => kept.get(k) ?? null, setItem: (k, v) => kept.set(k, v), removeItem: (k) => kept.delete(k) };
  const asked = [];
  const timers = [];
  let held = [{ key: KEY, value: "show", updated_ms: 7 }];
  let refuse = null;
  const applied = [];
  const statuses = [];
  const sync = SETTINGS.createSettingsSync({
    storage,
    clock: { setTimeout: (run, ms) => timers.push({ run, ms }), clearTimeout: () => {} },
    decoded: async (type, path, options) => {
      asked.push({ type, path, method: options?.method ?? "GET", body: options?.body });
      if (refuse) throw refuse;
      if (options?.method === "PUT") {
        for (const entry of [...options.body.seed, ...options.body.set]) held = held.filter((h) => h.key !== entry.key).concat([{ ...entry, updated_ms: 9 }]);
      }
      return { settings: held };
    },
    token: () => "tok",
    tokenScope: () => "write",
    apply: (key) => applied.push([key, kept.get(key) ?? null]),
    status: (text) => statuses.push(text),
    landed: () => {},
  });
  // Nothing goes out before the server is said to keep settings, nor before the token is proven.
  await sync.syncOnce();
  assert.equal(asked.length, 0, "asked before either");
  sync.setSupported(true);
  await sync.syncOnce();
  assert.equal(asked.length, 0, "asked with an unproven token");
  sync.forget();
  assert.equal(sync.start(), true, "the first start is the caller's to make the first pass of");
  await sync.syncOnce();
  assert.equal(asked.length, 0, "asked of a server not said to keep settings");
  sync.setSupported(true);
  await sync.syncOnce();
  // The server's held value wins over one that never moved; the one it does not hold is seeded.
  assert.deepStrictEqual(asked.map((a) => a.method), ["GET", "PUT"]);
  assert.deepStrictEqual(asked[1].body, { set: [], seed: [{ key: "vibe-talk.voice.combine", value: "1", updated_ms: 0 }] });
  assert.deepStrictEqual(applied, [[KEY, "show"]]);
  assert.deepStrictEqual(sync.agreed(KEY), { value: "show", updatedMs: 7 });
  // A change here is pushed on the next pass.
  kept.set(KEY, "hide");
  await sync.syncOnce();
  assert.deepStrictEqual(asked[2].body, { set: [{ key: KEY, value: "hide", updated_ms: 0 }], seed: [] });
  // The timer reschedules itself after each pass, on the clock port: armed once, and again only
  // once the pass it ran has ended.
  sync.keepPassing();
  assert.deepStrictEqual(timers.map((t) => t.ms), [1750]);
  timers[0].run();
  assert.equal(timers.length, 1, "the next pass was armed before this one ended");
  for (let i = 0; i < 5 && timers.length === 1; i += 1) await Promise.resolve();
  assert.deepStrictEqual(timers.map((t) => t.ms), [1750, 1750], "the timer did not re-arm after its pass");
  // A permanent refusal keeps everything local and stops asking.
  refuse = Object.assign(new Error("HTTP 404"), { status: 404 });
  kept.set(KEY, "show");
  await sync.syncOnce();
  assert.equal(statuses.at(-1), "This server does not keep settings, so yours stay on this device.");
  const before = asked.length;
  await sync.syncOnce();
  assert.equal(asked.length, before, "a server that keeps no settings was asked again");
  assert.equal(kept.get(KEY), "show", "a refusal cost this device its value");
});

test("`#624 voice-page-modularity`: each device setting reads, keeps and refuses as its own reader and writer always did", () => {
  const { DEVICE_SETTINGS, createDeviceSettings } = SETTINGS;
  const THROWN = Symbol("thrown");
  // [name, key, nothing kept, [[a value, what it keeps (null: forgotten)], ...], a refused read].
  const onOff = (name, key, absent, refused) => [name, key, absent, [[true, "1"], [false, "0"]], refused];
  const table = [
    onOff("inAppLinks", "vibe-talk.voice.in-app-links", true, THROWN),
    onOff("summarizeCollapsed", "vibe-talk.voice.summarize-collapsed", false, false),
    ["linksRaw", "vibe-talk.voice.link-raw-urls", false, [[true, "on"], [false, null]], false],
    onOff("composerGrow", "vibe-talk.voice.composer-grow", false, false),
    onOff("enterSends", "vibe-talk.voice.enter-sends", true, THROWN),
    onOff("singleKeys", "vibe-talk.voice.single-keys", true, true),
    onOff("richHeaders", "vibe-talk.voice.rich-headers", true, true),
    onOff("markOwnRead", "vibe-talk.voice.mark-own-read", true, THROWN),
    onOff("hideEmptyMessages", "vibe-talk.voice.hide-empty", true, THROWN),
    onOff("combineMessages", "vibe-talk.voice.combine", true, THROWN),
    ["openInView", "vibe-talk.voice.open-in-view", "flat", [["main", "main"], ["flat", "flat"]], THROWN],
    ["readAudioSource", "vibe-talk.voice.read-audio-source", null, [["agent", "agent"], ["device", "device"], ["wit", "wit"]], null],
    ["witVoice", "vibe-talk.voice.wit-voice", "", [["Charlie", "Charlie"], ["", null]], ""],
    ["readSteerOffset", "vibe-talk.voice.read-steer-offset", null, [[{ x: 3, y: -4 }, '{"x":3,"y":-4}'], [null, null]], null],
    ["slackOpen", "vibe-talk.voice.slack-open", "browser", [["app", "app"], ["browser", "browser"]], "browser"],
    ["threadsMain", "vibe-talk.voice.threads-main", false, [[true, "on"], [false, "off"]], false],
    ["threadCardFolded", "vibe-talk.voice.thread-card-folded", false, [[true, "on"], [false, "off"]], false],
    ["keyboardDebug", "vibe-talk.voice.keyboard-debug", false, [[true, "1"], [false, null]], false],
    ["msgScale", "vibe-talk.voice.msg-scale", 100, [[120, "120"], [80, "80"]], THROWN],
    ["readingWidth", "vibe-talk.voice.width", 72, [[90, "90"], [45, "45"]], THROWN],
    ["collapsedLines", "vibe-talk.voice.collapsed-lines", 3, [[0, "0"], [8, "8"]], THROWN],
    ["cardMaxLines", "vibe-talk.voice.thread-card-max-lines", 5, [[1, "1"], [12, "12"]], 5],
    ["readSpeed", "vibe-talk.voice.read-speed", null, [[150, "150"], [null, null]], THROWN],
  ];
  const refused = () => { throw new Error("SecurityError"); };
  const off = createDeviceSettings({ getItem: refused, setItem: refused, removeItem: refused });
  for (const [name, key, absent, values, whenRefused] of table) {
    const kept = new Map();
    const settings = createDeviceSettings({ getItem: (k) => kept.get(k) ?? null, setItem: (k, v) => kept.set(k, v), removeItem: (k) => kept.delete(k) });
    const setting = DEVICE_SETTINGS[name];
    assert.equal(setting.key, key, name);
    assert.deepStrictEqual(settings.get(setting), absent, `${name}: nothing kept`);
    for (const [value, keeps] of values) {
      settings.keep(setting, value);
      assert.deepStrictEqual([kept.get(key) ?? null, settings.get(setting)], [keeps, value], `${name}: ${JSON.stringify(value)}`);
      assert.equal(settings.keptAs(setting, value), true, `${name}: the read-back of ${JSON.stringify(value)}`);
    }
    if (whenRefused === THROWN) assert.throws(() => off.get(setting), /SecurityError/, `${name}: a refusal was swallowed`);
    else assert.deepStrictEqual(off.get(setting), whenRefused, `${name}: refused`);
    assert.throws(() => off.keep(setting, values[0][0]), /SecurityError/, `${name}: a refused write was swallowed`);
  }
  // What a reader made of a value it does not know, as before: the default, never the stray text.
  const stray = createDeviceSettings({ getItem: () => "{nonsense", setItem: () => {}, removeItem: () => {} });
  assert.deepStrictEqual([stray.get(DEVICE_SETTINGS.readAudioSource), stray.get(DEVICE_SETTINGS.openInView),
    stray.get(DEVICE_SETTINGS.slackOpen), stray.get(DEVICE_SETTINGS.readSteerOffset)], [null, "flat", "browser", null]);
  // ...and a number out of its range, or not a number at all, as the clamps always read it: held to
  // the range; the default, or for the pace no preference; a blank the default, never zero.
  const keptText = (text) => createDeviceSettings({ getItem: () => text, setItem: () => {}, removeItem: () => {} });
  assert.deepStrictEqual([keptText("4000").get(DEVICE_SETTINGS.readingWidth), keptText("1").get(DEVICE_SETTINGS.msgScale),
    keptText("99").get(DEVICE_SETTINGS.collapsedLines), keptText("0").get(DEVICE_SETTINGS.cardMaxLines),
    keptText("999").get(DEVICE_SETTINGS.readSpeed)], [120, 80, 8, 1, 200]);
  assert.deepStrictEqual([stray.get(DEVICE_SETTINGS.readingWidth), stray.get(DEVICE_SETTINGS.msgScale),
    stray.get(DEVICE_SETTINGS.collapsedLines), stray.get(DEVICE_SETTINGS.cardMaxLines), stray.get(DEVICE_SETTINGS.readSpeed)],
  [72, 100, 3, 5, null]);
  assert.deepStrictEqual([keptText("  ").get(DEVICE_SETTINGS.collapsedLines), keptText("").get(DEVICE_SETTINGS.readingWidth)], [3, 72]);
  assert.deepStrictEqual(Object.keys(DEVICE_SETTINGS).sort(), table.map(([name]) => name).sort(), "a setting with no row here");
});

test("`#624 voice-page-modularity`: the channel store's rules hold from the module alone: views, time order, threads", () => {
  const { emptyCanon, inTimeOrder, inViewOf, sameMessage, threadOf, timeOf, viewOfKey } = CHANNELS;
  const a = emptyCanon(42);
  const b = emptyCanon();
  assert.equal(a.channel, "42");
  assert.equal(b.channel, "");
  assert.notEqual(a.views, b.views, "two stores share a map");
  assert.deepStrictEqual([a.scope, a.complete, a.hasThreads, a.messages, a.threads], [null, null, false, [], []]);
  assert.deepStrictEqual(viewOfKey("thread:t1"), { view: "thread", thread: "t1" });
  assert.deepStrictEqual(viewOfKey("main"), { view: "main", thread: null });
  assert.ok(Number.isNaN(timeOf(null, "timestamp")) && Number.isNaN(timeOf({ timestamp: "never" }, "timestamp")));
  // Stable by time where every row has one; the server's order where one has none.
  const rows = [{ id: "b", timestamp: "2026-10-01T00:00:02Z" }, { id: "a", timestamp: "2026-10-01T00:00:01Z" },
    { id: "c", timestamp: "2026-10-01T00:00:01Z" }];
  assert.deepStrictEqual(inTimeOrder(rows, "timestamp").map((row) => row.id), ["a", "c", "b"]);
  const unknown = [...rows, { id: "d" }];
  assert.equal(inTimeOrder(unknown, "timestamp"), unknown, "a row with no time did not leave the order as given");
  // The server's timeline rule: All everything, a thread its own, Main roots and unthreaded, and in a
  // scoped channel its one conversation whole.
  const root = { id: "1", thread: { id: "t", is_root: true } };
  const reply = { id: "2", thread: { id: "t", is_root: false } };
  const plain = { id: "3" };
  assert.deepStrictEqual([root, reply, plain].map((m) => inViewOf(m, "main", null, null)), [true, false, true]);
  assert.deepStrictEqual([root, reply, plain].map((m) => inViewOf(m, "thread", "t", null)), [true, true, false]);
  assert.deepStrictEqual([root, reply, plain].map((m) => inViewOf(m, "flat", null, null)), [true, true, true]);
  assert.equal(inViewOf(reply, "main", null, "t"), true, "a scoped channel's reply is not on its Main");
  assert.deepStrictEqual([threadOf(reply), threadOf(plain), threadOf(null), threadOf({ thread: { id: 7 } })], ["t", null, null, null]);
  assert.equal(sameMessage({ id: "1", content: "x" }, { id: "1", content: "x" }), true);
  assert.equal(sameMessage({ content: "x", id: "1" }, { id: "1", content: "x" }), false, "fields in another order are another copy");
  assert.equal(sameMessage(undefined, undefined), false, "nothing held is never the arriving copy");
});

test("`#624 voice-page-modularity`: folding a page into a store, from the module alone: a newest page's window, older pages, removals below it", () => {
  const { emptyCanon, mergeIntoCanon, upsertThreadSummary, heldCopies } = CHANNELS;
  const at = (s) => `2026-10-01T00:00:${String(s).padStart(2, "0")}Z`;
  const m = (id, s) => ({ id, timestamp: at(s), content: `m${id}` });
  const canon = emptyCanon("c");
  canon.messages = [m("1", 1), m("2", 2), m("3", 3), m("4", 4)];
  const kept = canon.messages[2];
  // A newest page reaching back to 3 that says there is more: 4 is gone upstream; 1 and 2 are below it.
  mergeIntoCanon(canon, "messages", [m("3", 3), m("5", 5)], false, true, () => true);
  assert.deepStrictEqual(canon.messages.map((x) => x.id), ["1", "2", "3", "5"]);
  assert.equal(canon.messages[2], kept, "a copy held word for word did not keep the store's object");
  // ...but a message removed upstream below the window goes with the next newest page.
  canon.removed.set("1", 9);
  mergeIntoCanon(canon, "messages", [m("3", 3), m("5", 5)], false, true, () => true);
  assert.deepStrictEqual(canon.messages.map((x) => x.id), ["2", "3", "5"]);
  // An older page only adds; a newest page with nothing more answers for everything of its view.
  mergeIntoCanon(canon, "messages", [m("0", 0)], true, true, () => true);
  assert.deepStrictEqual(canon.messages.map((x) => x.id), ["0", "2", "3", "5"]);
  mergeIntoCanon(canon, "messages", [m("5", 5)], false, false, (x) => x.id !== "2");
  assert.deepStrictEqual(canon.messages.map((x) => x.id), ["2", "5"], "rows of another view were taken, or rows of this one kept");
  // A copy that lost its upstream address keeps the held one's.
  canon.messages = [{ ...m("7", 7), upstream_url: "https://example.com/7" }];
  mergeIntoCanon(canon, "messages", [{ ...m("7", 7), content: "edited" }], false, false, () => true);
  assert.deepStrictEqual([canon.messages[0].content, canon.messages[0].upstream_url], ["edited", "https://example.com/7"]);
  assert.deepStrictEqual([...heldCopies(canon, [{ id: "7" }, { id: "8" }]).keys()], ["7"]);
  // A thread summary replaces the one held by id, in time order.
  upsertThreadSummary(canon, { id: "t1", updated_at: at(5) });
  upsertThreadSummary(canon, { id: "t2", updated_at: at(3) });
  upsertThreadSummary(canon, { id: "t1", updated_at: at(1) });
  assert.deepStrictEqual(canon.threads.map((t) => t.id), ["t1", "t2"]);
});

test("`#624 voice-page-modularity`: the server's versions decide copies and absences, from the module alone", () => {
  const { serverVersions, pageCopyNewer, goneByAbsence, refreshFailed, exactCount, allPageAnswersFor, emptyCanon } = CHANNELS;
  assert.equal(serverVersions({}), null, "an older server's page has versions");
  assert.deepStrictEqual(serverVersions({ observed_ms: 10, settled_below_ms: 5 }), { observed: 10, settledBelow: 5 });
  assert.deepStrictEqual(serverVersions({ observed_ms: 10 }), { observed: 10, settledBelow: null });
  const versions = { observed: 100, settledBelow: Date.parse("2026-10-01T00:00:10Z") };
  assert.equal(pageCopyNewer(undefined, {}, versions), null);
  assert.equal(pageCopyNewer({ id: "1" }, {}, versions), null, "a copy that does not say how new it is was decided");
  assert.equal(pageCopyNewer({ observed_ms: 50, edited_timestamp: "2026-10-01T00:00:09Z" },
    { edited_timestamp: "2026-10-01T00:00:08Z" }, versions), false, "an earlier edit replaced a later one");
  assert.equal(pageCopyNewer({ observed_ms: 150 }, {}, versions), false);
  assert.equal(pageCopyNewer({ observed_ms: 50 }, {}, versions), true);
  assert.equal(goneByAbsence({ observed_ms: 50, timestamp: "2026-10-01T00:00:05Z" }, versions), true);
  assert.equal(goneByAbsence({ observed_ms: 150, timestamp: "2026-10-01T00:00:05Z" }, versions), false, "a copy newer than the read was taken away");
  assert.equal(goneByAbsence({ observed_ms: 50, timestamp: "2026-10-01T00:00:15Z" }, versions), false, "the unsettled band was taken as settled");
  assert.equal(goneByAbsence({ observed_ms: 50 }, { observed: 100, settledBelow: null }), false);
  assert.deepStrictEqual([refreshFailed({ refresh_failed: "x" }), refreshFailed({}), refreshFailed(null)], [true, false, false]);
  assert.deepStrictEqual([exactCount({ reply_count: 3 }), exactCount({ reply_count: 3, reply_count_exact: false }), exactCount(null)], [3, null, null]);
  // All's page answers for every reply of a thread it carries whole, and for the rest from its oldest carried reply up.
  const canon = emptyCanon("c");
  const t = (id, root, s, count) => ({ id, timestamp: `2026-10-01T00:00:0${s}Z`,
    thread: { id, is_root: root, reply_count: count ?? null, reply_count_exact: count !== undefined } });
  const page = [t("a", true, 1, 1), { ...t("a", false, 2), id: "a1" }, t("b", true, 3, 5), { ...t("b", false, 6), id: "b2" }];
  const answers = allPageAnswersFor(canon, page, true);
  assert.equal(answers({ ...t("a", false, 1), id: "a0" }), true, "a thread carried whole was not answered for");
  assert.equal(answers({ ...t("b", false, 4), id: "b1" }), false, "a reply below the oldest carried was answered for");
  assert.equal(answers({ ...t("c", false, 4), id: "c1" }), false, "a thread the page carries nothing of was answered for");
  canon.scope = "c";
  assert.equal(answers({ ...t("c", false, 4), id: "c1" }), true, "the scope was not read when the question was asked");
  // A removal as of the read numbered 5 is newer than reads up to 5, and older than read 6.
  const { removedSince, heldNow, deltaSideState } = CHANNELS;
  canon.removed.set("9", 5);
  assert.deepStrictEqual([removedSince(canon, "9", 5), removedSince(canon, "9", 6), removedSince(canon, "8", 0)], [true, false, false]);
  canon.messages = [{ id: 1 }, { id: "2" }];
  assert.deepStrictEqual([...heldNow(canon).keys()], ["1", "2"]);
  const before = deltaSideState(canon, { id: "t" });
  canon.replyGaps.set("t", 1);
  assert.notEqual(deltaSideState(canon, { id: "t" }), before, "a changed gap was not part of what a delta can change");
});

test("`#624 voice-page-modularity`: a view shows the store only from where its own pages reached, from the module alone", () => {
  const { emptyCanon, coverViewOf, projectionOf } = CHANNELS;
  const at = (s) => `2026-10-01T00:00:${String(s).padStart(2, "0")}Z`;
  const m = (id, s, thread) => ({ id, timestamp: at(s), ...(thread ? { thread } : {}) });
  const canon = emptyCanon("c");
  canon.messages = [m("1", 1), m("2", 2, { id: "t", is_root: false }), m("3", 3, { id: "t", is_root: true }), m("4", 4)];
  assert.equal(projectionOf(canon, "main", "main", null), null, "a view no page covered projected rows");
  // Main's newest page reached back to 3 and says there is more: 1 is below its floor, 2 is not Main's.
  coverViewOf(canon, "main", "main", [m("3", 3), m("4", 4)], false, true, "");
  const main = canon.views.get("main");
  assert.deepStrictEqual([main.floor, main.more, main.live, main.cursor, main.top], [Date.parse(at(3)), true, true, null, Date.parse(at(4))]);
  assert.deepStrictEqual(projectionOf(canon, "main", "main", null).map((x) => x.id), ["3", "4"]);
  // A step back to 1 lowers the floor; a refresh that stops short keeps the history already walked back to.
  coverViewOf(canon, "main", "main", [m("1", 1)], true, true, "");
  assert.equal(canon.views.get("main").floor, Date.parse(at(1)));
  coverViewOf(canon, "main", "main", [m("4", 4)], false, true, "");
  assert.equal(canon.views.get("main").floor, Date.parse(at(1)), "a refresh threw away history walked back to");
  assert.deepStrictEqual(projectionOf(canon, "main", "main", null).map((x) => x.id), ["1", "3", "4"]);
  // A newest page with nothing more: the whole view, and Main's own coverage proves nothing of All.
  coverViewOf(canon, "main", "main", [m("4", 4)], false, false, "a notice");
  assert.deepStrictEqual([canon.views.get("main").floor, canon.views.get("main").more, canon.views.get("main").notice], [null, false, "a notice"]);
  assert.equal(projectionOf(canon, "flat", "flat", null), null);
  coverViewOf(canon, "thread:t", "thread", [m("2", 2), m("3", 3)], false, false, "");
  assert.deepStrictEqual(projectionOf(canon, "thread:t", "thread", "t").map((x) => x.id), ["2", "3"]);
});

test("`#624 voice-page-modularity`: a channel's store saved and restored, from the module alone: what is kept, what is not, what is not trusted", () => {
  const { emptyCanon, savedTimelineOf, restoreCanon } = CHANNELS;
  const canon = emptyCanon("c");
  canon.messages = [{ id: "1", thread: { id: "t", is_root: true } }, { id: "2" }];
  canon.threads = [{ id: "t" }];
  canon.views.set("main", { floor: 5, more: true, notice: "", top: 9, dense: NaN, at: 7, live: true, cursor: "cur",
    newest: "next", fullAt: 3, fullSent: 2 });
  canon.dismissed = new Set(["1", "gone"]);
  canon.unplaced = new Set(["2", "gone"]);
  canon.removed = new Map([["2", 4], ["gone", 4]]);
  canon.replyGaps = new Map([["t", 3], ["other", 1]]);
  canon.passedOver = new Set(["t", "other"]);
  canon.settledByDone = new Map([["t", 2]]);
  canon.scope = null;
  const saved = savedTimelineOf(canon, 1234, { at: "2" });
  // Only what the store still holds, of messages and of threads; no cursor; a NaN is a null.
  assert.deepStrictEqual(saved.views, { main: { floor: 5, more: true, at: 7, notice: "", top: 9, dense: null } });
  assert.deepStrictEqual([saved.dismissed, saved.unplaced, saved.removed, saved.replyGaps, saved.passedOver, saved.settledByDone],
    [["1"], ["2"], ["2"], { t: 3 }, ["t"], { t: 2 }]);
  assert.deepStrictEqual([saved.mode, saved.usedAt, saved.bookmark], ["timeline", 1234, { at: "2" }]);
  assert.notEqual(saved.messages, canon.messages, "the save shares the store's list");
  const back = emptyCanon("c");
  restoreCanon(back, JSON.parse(JSON.stringify(saved)));
  assert.deepStrictEqual([...back.dismissed], ["1"]);
  assert.deepStrictEqual([...back.removed], [["2", 0]], "a removal came back with its old place in the order of reads");
  assert.deepStrictEqual(back.views.get("main"), { floor: 5, more: true, at: 7, notice: "", top: 9, dense: null, live: false, cursor: null });
  assert.deepStrictEqual([...back.replyGaps], [["t", 3]]);
  // A save from before passed-over threads and Done's settling were kept: its gaps, and All's cover, are not trusted.
  const old = { ...JSON.parse(JSON.stringify(saved)), views: { ...saved.views, flat: saved.views.main } };
  delete old.passedOver;
  delete old.settledByDone;
  const older = emptyCanon("c");
  restoreCanon(older, old);
  assert.deepStrictEqual([older.replyGaps.size, older.settledByDone.size, older.views.has("flat"), older.views.has("main")], [0, 0, false, true]);
});

test("`#624 voice-page-modularity`: the replies a store lacks for being old, by thread, from the module alone", () => {
  const { emptyCanon, noteReplyGapsIn, allReachesThread } = CHANNELS;
  const at = (s) => `2026-10-01T00:00:${String(s).padStart(2, "0")}Z`;
  const root = (id, s, count) => ({ id: `r${id}`, timestamp: at(s), thread: { id, is_root: true, reply_count: count, reply_count_exact: true } });
  const reply = (id, n, s) => ({ id: `${id}-${n}`, timestamp: at(s), thread: { id, is_root: false, reply_count: null, reply_count_exact: false } });
  const canon = emptyCanon("c");
  let asked = 0;
  const readAll = () => { asked += 1; };
  // A thread's own newest page with its count sets the gap: its count less the replies held.
  canon.messages = [root("t", 1, 5), reply("t", 1, 2), reply("t", 2, 3)];
  noteReplyGapsIn(canon, { messages: [], thread: { id: "t", reply_count: 5, reply_count_exact: true } }, "thread", false, false, new Map(), readAll);
  assert.equal(canon.replyGaps.get("t"), 3);
  // A step back that brings one more reply lowers it by one.
  canon.messages.push(reply("t", 3, 1));
  noteReplyGapsIn(canon, { messages: [reply("t", 3, 1)] }, "thread", true, false, new Map(), readAll);
  assert.equal(canon.replyGaps.get("t"), 2);
  // Main's newest page, with no read of All: no gap is set for a thread it is first to name, and All is read behind it.
  canon.messages.push(root("u", 6, 4));
  noteReplyGapsIn(canon, { messages: [root("u", 6, 4)] }, "main", false, false, new Map(), readAll);
  assert.deepStrictEqual([canon.replyGaps.has("u"), asked], [false, 1]);
  // A scoped channel, or the thread list, says nothing of gaps.
  canon.scope = "u";
  noteReplyGapsIn(canon, { messages: [root("u", 6, 4)] }, "main", false, false, new Map(), readAll);
  assert.equal(asked, 1, "a scoped channel asked for All");
  canon.scope = null;
  // All's cover reaches a thread whose root is no older than its floor, or All is the whole channel.
  assert.equal(allReachesThread(canon, "u", null), false, "All reached a thread with no read of All");
  canon.views.set("flat", { floor: Date.parse(at(4)), more: true, notice: "", top: null, dense: null, at: 0, live: true, cursor: null });
  assert.deepStrictEqual([allReachesThread(canon, "u", null), allReachesThread(canon, "t", null)], [true, false]);
  canon.views.get("flat").more = false;
  assert.equal(allReachesThread(canon, "t", null), true);
});

test("`#624 voice-page-modularity`: the copy-order ledger, from the module alone: where a copy stands, what it was built on, what says it as posted", () => {
  const { createCopyOrder, emptyCanon } = CHANNELS;
  const ledger = createCopyOrder();
  const read = { id: "1" };
  ledger.place(read, 5);
  assert.deepStrictEqual([ledger.copyOlderThan(read, "1", 6, new Map()), ledger.copyOlderThan(read, "1", 5, new Map())], [true, false]);
  // Later only: an older read does not move a copy back.
  ledger.orderCopy(read, 3);
  assert.equal(ledger.copyOlderThan(read, "1", 4, new Map()), false, "an older read moved the copy back");
  // A copy built on another stands where that one stood, and inherits "as posted".
  const live = { id: "2" };
  ledger.place(live, 2);
  ledger.markPosted(live);
  const counted = { id: "2", thread: {} };
  ledger.buildCopyOn(counted, live);
  assert.deepStrictEqual([ledger.isPosted(counted), ledger.copyOlderThan(counted, "2", 3, new Map())], [true, true]);
  assert.equal(ledger.copyOlderThan(counted, "2", 1, new Map(), true), true, "a posted copy was not older in what it says");
  // A read that brings the copy speaks for it from then on: no longer built on, as new as the read.
  const canon = emptyCanon("c");
  canon.messages = [counted];
  ledger.orderCopiesRead(canon, [{ id: "2" }], 9);
  assert.equal(ledger.copyOlderThan(counted, "2", 9, new Map()), false);
  // A copy with no place (saved on the device) is older exactly when the store held it as the read was sent.
  const saved = { id: "3" };
  assert.deepStrictEqual([ledger.copyOlderThan(saved, "3", 1, new Map([["3", saved]])), ledger.copyOlderThan(saved, "3", 1, new Map())], [true, false]);
  // Two ledgers share nothing.
  assert.equal(createCopyOrder().isPosted(live), false);
});

test("`#624 voice-page-modularity`: what a page may fold, from the module alone, with the page's questions injected", () => {
  const { emptyCanon, pageFoldIn, createCopyOrder } = CHANNELS;
  const canon = emptyCanon("c");
  const asked = [];
  const deps = (over = {}) => ({
    number: 5, ledger: createCopyOrder(),
    removedAfterRead: () => false,
    newerPageSpeaksFor: (_canon, message) => { asked.push(message.id); return message.id === "spoken"; },
    ownPostStands: (id) => id === "mine",
    ...over,
  });
  // No store as it was sent: every copy taken; every message answered for, but a fresh own post.
  const plain = pageFoldIn(canon, { messages: [] }, null, deps());
  assert.deepStrictEqual([plain.takes({ id: "1" }), plain.answers({ id: "1" }), plain.answers({ id: "mine" })], [true, true, false]);
  // A removal newer than the read: never taken, always answered for, whatever the page carries.
  canon.removed.set("gone", 7);
  assert.deepStrictEqual([plain.takes({ id: "gone" }), plain.answers({ id: "gone" })], [false, true]);
  // With the store as it was sent: a message never held is taken unless a newer page speaks for it.
  const late = pageFoldIn(canon, { messages: [] }, new Map(), deps());
  assert.deepStrictEqual([late.takes({ id: "new" }), late.takes({ id: "spoken" })], [true, false]);
  assert.deepStrictEqual(asked, ["new", "spoken"]);
  // The server's record of removals is asked too.
  const removedLate = pageFoldIn(canon, { messages: [] }, null, deps({ removedAfterRead: (_c, id) => id === "x" }));
  assert.deepStrictEqual([removedLate.takes({ id: "x" }), removedLate.answers({ id: "x" })], [false, true]);
});

test("`#624 voice-page-modularity`: the record of removals, from the module alone: by the order of reads and by the server's clock", () => {
  const { emptyCanon, createRemovals, forgetUnplaced } = CHANNELS;
  const removals = createRemovals();
  const canon = emptyCanon("c");
  canon.unplaced.add("1");
  canon.unplacedSince.set("1", 3);
  removals.noteRemoved(canon, "1", 4, 1000);
  assert.deepStrictEqual([canon.unplaced.has("1"), canon.unplacedSince.has("1"), canon.removed.get("1")], [false, false, 4]);
  // The server observed the removal at 1000: a page whose read began at or before then is older than it.
  assert.deepStrictEqual([removals.removedAfterRead(canon, "1", { observed: 900, settledBelow: null }),
    removals.removedAfterRead(canon, "1", { observed: 1100, settledBelow: null }), removals.removedAfterRead(canon, "1", null)], [true, false, false]);
  // A read sent after the removal that still carries the message believes it; one sent before does not.
  let asked = 0;
  removals.believeCarried(canon, { messages: [{ id: "1" }] }, () => { asked += 1; return 3; });
  assert.equal(canon.removed.has("1"), true, "a read sent before the removal brought the message back");
  removals.believeCarried(canon, { messages: [{ id: "1" }], observed_ms: 900 }, () => 9);
  assert.equal(canon.removed.has("1"), true, "a read begun before the server observed the removal brought it back");
  removals.believeCarried(canon, { messages: [{ id: "1" }], observed_ms: 1100 }, () => 9);
  assert.equal(canon.removed.has("1"), false, "a read sent after the removal that carries the message was not believed");
  assert.equal(removals.removedAfterRead(canon, "1", { observed: 900, settledBelow: null }), false, "the server's record of a believed message stayed");
  // Nothing removed: the read's place in the order is not even asked.
  removals.believeCarried(emptyCanon("d"), { messages: [{ id: "1" }] }, () => { asked += 1; return 0; });
  assert.equal(asked, 1);
  forgetUnplaced(canon, "nothing");
});

test("`#624 voice-page-modularity`: a delta folded into a store, from the module alone, the page's part injected", () => {
  const { emptyCanon, foldDeltaIn, createCopyOrder, createRemovals } = CHANNELS;
  const at = (s) => `2026-10-01T00:00:${String(s).padStart(2, "0")}Z`;
  const canon = emptyCanon("c");
  const held = { id: "1", timestamp: at(1), content: "a" };
  canon.messages = [held, { id: "2", timestamp: at(2), content: "b" }];
  canon.views.set("main", { floor: null, more: false, notice: "", top: null, dense: null, at: 0, live: false, cursor: null, newest: "cur" });
  const seen = [];
  const deps = {
    ledger: createCopyOrder(), removals: createRemovals(),
    numberOf: () => 7, readsSent: () => 6,
    forgetArchived: (id) => seen.push(["archived", id]),
    foldReadState: () => { seen.push(["read"]); return false; },
    noteReplyGaps: (before) => seen.push(["gaps", [...before.keys()]]),
    markUnchanged: () => seen.push(["unchanged"]),
    staleAsOf: () => null,
  };
  const delta = (over) => ({ messages: [], delta: { deleted: [], removed_threads: [], complete: true }, next_after: "next", ...over });
  // A cursor the cover no longer holds: nothing touched.
  assert.equal(foldDeltaIn(canon, delta({}), "old", "main", "main", deps), false);
  assert.deepStrictEqual(seen, []);
  // A deletion, an edit and a copy held word for word.
  const changed = delta({ messages: [{ ...held }, { id: "2", timestamp: at(2), content: "edited" }],
    delta: { deleted: ["9"], removed_threads: [], complete: true } });
  canon.messages.push({ id: "9", timestamp: at(9), content: "gone" });
  assert.equal(foldDeltaIn(canon, changed, "cur", "main", "main", deps), true);
  assert.deepStrictEqual(canon.messages.map((m) => m.content), ["a", "edited"]);
  assert.equal(canon.messages[0], held, "a copy held word for word lost the store's object");
  assert.deepStrictEqual([canon.removed.get("9"), canon.complete, canon.views.get("main").newest, canon.views.get("main").live], [6, true, "next", true]);
  assert.deepStrictEqual(seen, [["archived", "9"], ["read"], ["gaps", ["1", "2"]]], "the page's part came in another order");
  // A delta that changes nothing is marked so.
  seen.length = 0;
  assert.equal(foldDeltaIn(canon, delta({ messages: [] }), "next", "main", "main", deps), true);
  assert.deepStrictEqual(seen.map(([what]) => what), ["read", "gaps", "unchanged"]);
});

test("`#624 voice-page-modularity`: a live arrival folded into a store, from the module alone", () => {
  const { emptyCanon, foldLiveIn, createCopyOrder, namedRecord } = CHANNELS;
  const at = (s) => `2026-10-01T00:00:${String(s).padStart(2, "0")}Z`;
  const canon = emptyCanon("c");
  let arrivals = 0;
  const ledger = createCopyOrder();
  const deps = { ledger, orderNow: () => 4.5, nextArrival: () => ++arrivals };
  const root = { id: "r", timestamp: at(1), thread: { id: "t", is_root: true, reply_count: 2, reply_count_exact: true, display_name: "Plans", summary: "s" },
    reactions: [{ emoji: "x", count: 1 }], edited_timestamp: at(2), upstream_url: "https://example.com/r" };
  canon.messages = [root];
  canon.threads = [{ id: "t", updated_at: at(1), reply_count: 2, reply_count_exact: true }];
  // The stream's copy of the root, bare: it keeps the store's thread record, reactions, edit mark, address and name.
  const bare = { id: "r", timestamp: at(1), content: "root" };
  const kept = foldLiveIn(canon, bare, true, false, null, deps);
  assert.deepStrictEqual([kept.thread.id, kept.reactions.length, kept.edited_timestamp, kept.upstream_url, kept.thread.display_name],
    ["t", 1, at(2), "https://example.com/r", "Plans"]);
  assert.equal(ledger.isPosted(kept), true, "the stream's copy does not say the message as it was posted");
  // A new reply from the stream counts on its thread's summary and on the root's copy.
  const reply = { id: "1", timestamp: at(5), thread: { id: "t", is_root: false, reply_count: null, reply_count_exact: false } };
  foldLiveIn(canon, reply, true, false, null, deps);
  assert.deepStrictEqual([canon.threads[0].reply_count, canon.messages.find((m) => m.id === "r").thread.reply_count], [3, 3]);
  // ...but a replayed copy does not.
  foldLiveIn(canon, { ...reply, id: "2", timestamp: at(6) }, true, true, null, deps);
  assert.equal(canon.threads[0].reply_count, 3);
  // A bare live copy of a message no page placed is unplaced, numbered in the order of arrivals.
  foldLiveIn(canon, { id: "u", timestamp: at(7) }, true, false, null, deps);
  assert.deepStrictEqual([canon.unplaced.has("u"), canon.unplacedSince.get("u")], [true, 1]);
  assert.deepStrictEqual([namedRecord(root), namedRecord(reply), namedRecord(null)], [root.thread, null, null]);
});

test("`#624 voice-page-modularity`: an unplaced message placed by a read, and which newer pages speak for it, from the module alone", () => {
  const { emptyCanon, placeFromPageIn, newerPage, newerPageSpeaksFor, answeredThread, createCopyOrder } = CHANNELS;
  const canon = emptyCanon("c");
  const reply = { id: "1", timestamp: "2026-10-01T00:00:01Z", thread: { id: "t", is_root: false } };
  const bare = { id: "1", timestamp: "2026-10-01T00:00:01Z" };
  assert.deepStrictEqual([answeredThread(reply), answeredThread(bare), answeredThread({ id: "r", thread: { id: "t", is_root: true } })], ["t", null, null]);
  canon.views.set("thread:t", { floor: null, more: false, notice: "", top: null, dense: null, at: 0, live: true, cursor: null, fullSent: 5 });
  assert.deepStrictEqual([newerPage(canon, "thread", 4, "t"), newerPage(canon, "thread", 5, "t"), newerPage(canon, "main", 0)], [true, false, false]);
  assert.deepStrictEqual([newerPageSpeaksFor(canon, reply, 4), newerPageSpeaksFor(canon, bare, 4)], [true, false]);
  // The stream's bare copy, unplaced; a read's answer carrying its thread record places it.
  const ledger = createCopyOrder();
  canon.messages = [bare];
  canon.unplaced.add("1");
  assert.equal(placeFromPageIn({ messages: [reply] }, canon, 6, null, ledger), true);
  assert.deepStrictEqual([canon.unplaced.has("1"), canon.messages[0].thread.id], [false, "t"]);
  // Nothing unplaced: nothing placed.
  assert.equal(placeFromPageIn({ messages: [reply] }, canon, 6, null, ledger), false);
  // One the store lost, put back unless a newer page that speaks for it has landed.
  canon.messages = [];
  canon.unplaced.add("1");
  assert.equal(placeFromPageIn({ messages: [reply] }, canon, 4, null, ledger), false, "a reply a newer thread page speaks for came back");
  canon.unplaced.add("1");
  assert.equal(placeFromPageIn({ messages: [reply] }, canon, 6, null, ledger), true);
  assert.deepStrictEqual(canon.messages.map((m) => m.id), ["1"]);
});

test("`#624 voice-page-modularity`: a page folded into a store, from the module alone, the page's part injected in order", () => {
  const { emptyCanon, foldPageIn, createCopyOrder, createRemovals } = CHANNELS;
  const at = (s) => `2026-10-01T00:00:${String(s).padStart(2, "0")}Z`;
  const canon = emptyCanon("c");
  const seen = [];
  const deps = {
    ledger: createCopyOrder(), removals: createRemovals(), numberOf: () => 3,
    foldOf: (held) => { seen.push(["fold", held]); return { takes: () => true, answers: () => true }; },
    scopeChanged: () => seen.push(["scope"]),
    staleAsOf: () => null,
    foldReadState: () => seen.push(["read"]),
    noteReplyGaps: (before) => seen.push(["gaps", before.size]),
  };
  const page = { messages: [{ id: "1", timestamp: at(1) }, { id: "2", timestamp: at(2) }], has_more: true, has_threads: true,
    next_after: "cur", thread: { id: "t" } };
  foldPageIn(canon, page, false, "main", null, "main", null, deps);
  assert.deepStrictEqual(canon.messages.map((m) => m.id), ["1", "2"]);
  assert.deepStrictEqual([canon.scope, canon.hasThreads], ["t", true], "a page naming its thread did not scope the channel");
  const cover = canon.views.get("main");
  assert.deepStrictEqual([cover.newest, cover.fullSent, cover.more, cover.floor], ["cur", 3, true, Date.parse(at(1))]);
  assert.deepStrictEqual(seen, [["scope"], ["fold", null], ["read"], ["gaps", 0]], "the page's part came in another order");
  // A page the server answered from its own copy moves no cover, cursor or full read.
  seen.length = 0;
  foldPageIn(canon, { ...page, refresh_failed: "slow", next_after: "other" }, false, "main", null, "main", null, deps);
  assert.equal(canon.views.get("main").newest, "cur", "a failed refresh moved the forward cursor");
  assert.deepStrictEqual(seen.map(([what]) => what), ["fold", "read", "gaps"], "a scope that did not change asked for columns");
});

test("`#624 voice-page-modularity`: what a store holds of every thread's replies, and what their counts say, from the module alone", () => {
  const { emptyCanon, replyTallyOf, exactReplyCount, tallyRecord, unseenRepliesIn, emptyTally } = CHANNELS;
  const canon = emptyCanon("c");
  const root = { id: "r", thread: { id: "t", is_root: true, reply_count: 4, reply_count_exact: true } };
  const reply = (id) => ({ id, thread: { id: "t", is_root: false } });
  canon.messages = [root, reply("1"), reply("2")];
  canon.threads = [{ id: "t", reply_count: 3, reply_count_exact: true, root: { id: "r" } }];
  canon.dismissed = new Set(["1"]);
  const tally = replyTallyOf(canon, (message, done) => !done.has(String(message.id)));
  assert.deepStrictEqual(tally.threads.get("t"), { held: 2, unread: 1 });
  assert.equal(tally.byRoot.get("r").id, "t");
  // The highest exact count of summary, the store's record and the one given; a count not said exact is none.
  assert.equal(exactReplyCount("t", root, tally), 4);
  assert.equal(exactReplyCount("t", root, tally, { reply_count: 9, reply_count_exact: true }), 9);
  assert.equal(exactReplyCount("x", null, emptyTally()), null);
  // Unseen: the count less what is held and what is known old.
  assert.equal(unseenRepliesIn(canon, "t", root, tally), 2);
  canon.replyGaps.set("t", 1);
  assert.equal(unseenRepliesIn(canon, "t", root, tally), 1);
  // A root whose copy came without a record has its summary's.
  assert.deepStrictEqual(tallyRecord({ id: "r" }, { ...emptyTally(), byRoot: new Map([["r", { id: "t", reply_count: 3, reply_count_exact: true }]]) }),
    { id: "t", root_message_id: "r", is_root: true, reply_count: 3, reply_count_exact: true });
  // A scoped channel's replies are not a thread's.
  canon.scope = "t";
  assert.equal(replyTallyOf(canon, () => true).threads.has("t"), false);
});

test("`#624 voice-page-modularity`: the channel store's owner opens a channel afresh and answers the current store", () => {
  const { createChannelStore } = CHANNELS;
  const store = createChannelStore();
  const first = store.current();
  assert.equal(first.channel, "");
  first.messages.push({ id: "1" });
  const opened = store.open(42);
  assert.equal(store.current(), opened);
  assert.deepStrictEqual([opened.channel, opened.messages.length], ["42", 0], "a channel opened did not start afresh");
  assert.equal(store.open().channel, "");
  assert.notEqual(createChannelStore().current(), store.current(), "two owners share a store");
});

test("`#624 voice-page-modularity`: the reading bookmark's owner, from the module alone: a read's word, the owner's move ahead of its write, settling it", () => {
  const { createBookmarks, sameAnchor, isBookmarkState, anchorOfMessage } = ANNOTATIONS;
  let epoch = 0;
  const store = createBookmarks({ bumpEpoch: () => ++epoch });
  const a = anchorOfMessage({ id: "1", timestamp: "t1", thread: { id: "th" } }, "above");
  const b = anchorOfMessage({ id: "2", timestamp: "t2" }, "below");
  assert.deepStrictEqual(a, { message_id: "1", place: "above", timestamp: "t1", thread_id: "th" });
  assert.deepStrictEqual([sameAnchor(a, a), sameAnchor(a, b), sameAnchor(null, undefined), isBookmarkState({ revision: 1, anchor: null })], [true, false, true, true]);
  // A read's word is taken while nothing of this page's is on its way.
  assert.equal(store.note("c", { revision: 3, anchor: a }, 0), true);
  assert.deepStrictEqual(store.held("c"), { revision: 3, anchor: a, token: null, known: true });
  assert.equal(store.toSave("c").revision, 3);
  // The owner's move: at once, before the write; a read meanwhile, or sent before the write settled, is not taken.
  const move = store.stage("c", b);
  assert.deepStrictEqual([store.held("c").anchor, store.writing("c"), epoch], [b, true, 1]);
  assert.equal(store.note("c", { revision: 4, anchor: a }, 5), false, "a read taken while a write was on its way");
  store.writeEnded("c");
  assert.deepStrictEqual([store.writing("c"), epoch], [false, 2]);
  assert.equal(store.note("c", { revision: 4, anchor: a }, 1), false, "a read sent before the write settled was taken");
  // Settled by the server's answer, still this move's: its revision and its anchor.
  assert.deepStrictEqual(store.settle(move, { bookmark: { revision: 5, anchor: b } }), { mine: true, before: b, after: b });
  assert.equal(store.held("c").revision, 5);
  // A failed write is taken back.
  const failed = store.stage("c", null);
  store.writeEnded("c");
  assert.deepStrictEqual(store.settle(failed, null), { mine: true, before: null, after: b });
  // A saved copy shows only where nothing newer is held; forgetting the credential forgets them all.
  store.restoreSaved("c", { revision: 1, anchor: a });
  assert.equal(store.held("c").revision, 5);
  store.forget();
  assert.equal(store.held("c"), null);
  assert.equal(store.settle(move, null), null, "a write settled after its credential was forgotten");
});

test("`#624 voice-page-modularity`: which reads still speak for a message's read state, from the module alone", () => {
  const { createReadLedger } = ANNOTATIONS;
  const ledger = createReadLedger();
  const before = {};
  ledger.noteSent(before, ledger.epoch());
  assert.equal(ledger.speaksFor(before, "1"), true, "a read spoke for nothing it wrote");
  ledger.writeStarted(["1"]);
  const during = {};
  ledger.noteSent(during, ledger.epoch());
  assert.deepStrictEqual([ledger.speaksFor(before, "1"), ledger.speaksFor(during, "1"), ledger.written("1")], [false, false, true]);
  ledger.writeSettled(["1"]);
  const after = {};
  ledger.noteSent(after, ledger.epoch());
  assert.deepStrictEqual([ledger.speaksFor(during, "1"), ledger.speaksFor(after, 1)], [false, true],
    "a read sent while the write was out spoke after it settled, or one sent after did not");
  // Two writes on their way: settling one is not enough.
  ledger.writeStarted(["2"]);
  ledger.writeStarted(["2"]);
  ledger.writeSettled(["2"]);
  assert.equal(ledger.speaksFor({}, "2"), false);
  // A payload no read sent is now, and holds the local state already; a seeded message speaks from its epoch.
  ledger.seed("3", ledger.bump());
  assert.equal(ledger.speaksFor({}, "3"), true);
  assert.deepStrictEqual([...ledger.writtenIds()], ["1", "2", "3"]);
});

test("`#624 voice-page-modularity`: the pinned messages' owner, from the module alone: a list, changes laid over it, answers and refusals", () => {
  const { createPins } = ANNOTATIONS;
  const pins = createPins();
  const pin = (id) => ({ message_id: id, content: `m${id}` });
  pins.forget("c");
  assert.deepStrictEqual([pins.channel(), pins.revision(), pins.size()], ["c", null, 0]);
  // A change asked for and not answered survives a list read meanwhile.
  pins.stage("2", pin("2"));
  pins.apply({ pins: [pin("1")], revision: 4, limit: 50 });
  assert.deepStrictEqual(pins.entries().map(([id]) => id), ["1", "2"]);
  assert.deepStrictEqual([pins.revision(), pins.limit(), pins.isPinned("c", 2), pins.isPinned("d", "2")], [4, 50, true, false]);
  // Answered: the server's pin, and the oldest it unpinned to make room.
  pins.answered("2", { ...pin("2"), content: "server's" }, ["1"]);
  assert.deepStrictEqual(pins.entries().map(([id, held]) => [id, held.content]), [["2", "server's"]]);
  // Refused: what was held before, back.
  const before = pins.held("2");
  pins.stage("2", null);
  assert.equal(pins.isPinned("c", "2"), false);
  pins.rollback("2", before);
  assert.equal(pins.held("2"), before);
  // One read in flight; a newer one supersedes it; a failure says why.
  const first = pins.startRead("c");
  const second = pins.startRead("c");
  assert.deepStrictEqual([pins.isCurrent(first), pins.isCurrent(second)], [false, true]);
  pins.endRead(first);
  assert.equal(pins.inFlight(), second, "an old read's end ended the current one");
  pins.failed("no answer");
  assert.equal(pins.problem(), "no answer");
  pins.forget("d");
  assert.deepStrictEqual([pins.channel(), pins.problem(), pins.inFlight(), pins.size()], ["d", "", null, 0]);
});

test("`#624 voice-page-modularity`: Done in the store at once, and taken back exactly when its write fails, from the module alone", () => {
  const { emptyCanon, markDoneIn, settleDoneIn } = CHANNELS;
  const unread = (message, done) => !done.has(String(message.id));
  const canon = emptyCanon("c");
  const root = { id: "r", thread: { id: "t", is_root: true, reply_count: 3, reply_count_exact: true } };
  canon.messages = [root, { id: "1", thread: { id: "t", is_root: false } }];
  canon.dismissed = new Set(["1"]);
  // Done on the root, from Main: the store at once, and its thread's unplaced replies settled.
  const mark = markDoneIn(canon, ["r", "1"], true, true, unread);
  assert.deepStrictEqual([mark.flipped, [...canon.dismissed].sort(), mark.settled], [["r"], ["1", "r"], [["t", 2]]]);
  assert.deepStrictEqual([canon.replyGaps.get("t"), canon.settledByDone.get("t")], [2, 2]);
  // The write failed: exactly what it changed goes back.
  settleDoneIn(mark, false);
  assert.deepStrictEqual([[...canon.dismissed], canon.replyGaps.has("t"), canon.settledByDone.has("t")], [["1"], false, false]);
  // Succeeded: nothing taken back.
  const kept = markDoneIn(canon, ["r"], true, true, unread);
  settleDoneIn(kept, true);
  assert.equal(canon.dismissed.has("r"), true);
  // Put back takes back what Done settled; failing, it is settled again.
  const back = markDoneIn(canon, ["r"], false, false, unread);
  assert.deepStrictEqual([canon.dismissed.has("r"), canon.replyGaps.has("t"), back.unsettled], [false, false, [["t", 2]]]);
  settleDoneIn(back, false);
  assert.deepStrictEqual([canon.dismissed.has("r"), canon.replyGaps.get("t")], [true, 2]);
  // No store for the channel on screen: nothing changed, nothing to take back.
  const none = markDoneIn(null, ["x"], true, true, unread);
  assert.deepStrictEqual([none.flipped, none.settled, none.unsettled, none.canon], [[], [], [], null]);
  settleDoneIn(none, false);
});

test("`#624 voice-page-modularity`: the reader's writes run one after another, a failure stopping none after it, from the module alone", async () => {
  const { createSerialQueue } = GLYPHS;
  const queue = createSerialQueue();
  const order = [];
  let release;
  const first = queue.run(() => new Promise((resolve) => { release = resolve; }).then(() => { order.push("first"); return 1; }));
  const second = queue.run(async () => { order.push("second"); throw new Error("refused"); });
  const third = queue.run(async () => { order.push("third"); return 3; });
  await Promise.resolve();
  assert.deepStrictEqual(order, [], "a task started before the one ahead of it settled");
  release();
  assert.equal(await first, 1);
  await assert.rejects(second, /refused/);
  assert.equal(await third, 3, "a failure stopped the task after it");
  assert.deepStrictEqual(order, ["first", "second", "third"]);
});

test("`#624 voice-page-modularity`: when a lost send goes out again by itself, and the waits, from the module alone", () => {
  const { nextRetryAt, outgoingRetryWait, retriesItself, OUTGOING_RETRY_ATTEMPTS } = OUTBOX;
  const once = () => true;
  const never = () => false;
  assert.deepStrictEqual([0, 1, 2, 3, 4, 5].map(outgoingRetryWait), [3000, 6000, 12000, 20000, 20000, 20000]);
  const keyed = { keyedOnly: true, channel: "c" };
  assert.deepStrictEqual([retriesItself(keyed, once), retriesItself(keyed, never), retriesItself({ channel: "c" }, once)], [true, false, false]);
  assert.equal(retriesItself({ ...keyed, postedCount: 1, replyTo: "9" }, once), false, "a remainder starting with the reply went again");
  assert.equal(retriesItself({ ...keyed, postedCount: 1, replyTo: "9", continueIn: "t" }, once), true);
  // From when the failed attempt started, never sooner than the floor; none after the last attempt.
  assert.equal(nextRetryAt(keyed, 1000, 1500, once), 4000);
  assert.equal(nextRetryAt(keyed, 1000, 60000, once), 61000, "a slow failure waited a full wait again");
  assert.equal(nextRetryAt({ ...keyed, retriesUsed: OUTGOING_RETRY_ATTEMPTS }, 0, 0, once), null);
  assert.equal(nextRetryAt({ channel: "c" }, 0, 0, once), null, "a send that may post twice went again");
  assert.equal(nextRetryAt({ channel: "c" }, 0, 0, never, true), 3000, "an attempt that posted nothing did not go again");
});

test("`#624 voice-page-modularity`: the recently dismissed, kept, pruned and saved, from the module alone", () => {
  const { createDismissedSends, DISMISSED_SENDS_LIMIT, DISMISSED_SENDS_DAYS } = OUTBOX;
  const day = 24 * 60 * 60 * 1000;
  const saved = new Map();
  const record = { refuse: 0, roomMade: 0 };
  const storage = {
    getItem: (key) => saved.get(key) ?? null,
    // A full quota refuses the next `refuse` writes without a word; the read back is what notices.
    setItem: (key, value) => { if (record.refuse > 0) record.refuse -= 1; else saved.set(key, value); },
    removeItem: (key) => saved.delete(key),
  };
  let now = 100 * day;
  const owner = () => createDismissedSends({
    storage, now: () => now, makeRoom: () => { record.roomMade += 1; },
    decode: (entry) => (entry && typeof entry.id === "string" ? { ...entry } : null),
  });
  const sends = owner();
  assert.equal(sends.add({ id: "a", text: "one" }), true);
  now += 1;
  assert.equal(sends.add({ id: "b", text: "two" }), true);
  now += 1;
  assert.equal(sends.add({ id: "a", text: "one again" }), true);
  assert.deepStrictEqual(sends.list().map((held) => held.entry.text), ["one again", "two"], "not newest first, or a copy kept twice");
  assert.equal(sends.find("b").at, 100 * day + 1);
  assert.deepStrictEqual(JSON.parse(saved.get("vibe-talk.dismissed-sends")), sends.list());
  // Another page of the same device reads it back.
  const again = owner();
  again.load();
  assert.deepStrictEqual(again.list(), sends.list());
  // The quota full once: the saved rows go, and the second write stands.
  record.refuse = 1;
  assert.equal(sends.remove(sends.find("b")), true);
  assert.equal(record.roomMade, 1);
  record.refuse = 2;
  assert.equal(sends.add({ id: "c" }), false, "a copy the device refused was reported kept");
  assert.equal(record.roomMade, 2);
  // Only the newest DISMISSED_SENDS_LIMIT, none older than DISMISSED_SENDS_DAYS.
  for (let i = 0; i < DISMISSED_SENDS_LIMIT + 3; i += 1) sends.add({ id: `n${i}` });
  assert.equal(sends.list().length, DISMISSED_SENDS_LIMIT);
  assert.equal(sends.list()[0].entry.id, `n${DISMISSED_SENDS_LIMIT + 2}`);
  now += DISMISSED_SENDS_DAYS * day;
  sends.prune();
  assert.deepStrictEqual(sends.list(), [], "a send past its days was kept");
  assert.notEqual(saved.get("vibe-talk.dismissed-sends"), undefined, "a prune alone rewrote the device's copy");
  // Loading prunes, and saves what it pruned; a damaged entry or copy is nothing.
  const late = owner();
  late.load();
  assert.deepStrictEqual(late.list(), []);
  assert.equal(saved.has("vibe-talk.dismissed-sends"), false);
  saved.set("vibe-talk.dismissed-sends", JSON.stringify([{ entry: { id: "x" }, at: now }, { entry: null, at: now }, { entry: { id: "y" }, at: "soon" }]));
  late.load();
  assert.deepStrictEqual(late.list().map((held) => held.entry.id), ["x"]);
  saved.set("vibe-talk.dismissed-sends", "{not json");
  late.load();
  assert.deepStrictEqual(late.list(), []);
  assert.equal(late.clear(), true);
});

test("`#624 voice-page-modularity`: the page's own posts, kept in their grace and shared by the device's windows, from the module alone", () => {
  const { createOwnPosts, OWN_POST_GRACE_MS } = OUTBOX;
  const saved = new Map();
  let full = false;
  const storage = {
    getItem: (key) => saved.get(key) ?? null,
    setItem: (key, value) => { if (full) throw new Error("quota"); saved.set(key, value); },
    removeItem: (key) => saved.delete(key),
  };
  let now = 1000;
  const owner = () => createOwnPosts({ storage, now: () => now });
  const page = owner();
  page.noteSent(["a", "b"]);
  assert.deepStrictEqual(JSON.parse(saved.get("vibe-talk.own-posts")), { a: 1000, b: 1000 });
  // Another window adds its own to what this one saved; a reload takes back both.
  now = 2000;
  const other = owner();
  other.noteSent(["c"]);
  assert.deepStrictEqual(JSON.parse(saved.get("vibe-talk.own-posts")), { a: 1000, b: 1000, c: 2000 });
  const reloaded = owner();
  reloaded.load();
  assert.equal(reloaded.stands("c"), true);
  assert.equal(reloaded.sentAt("a"), 1000);
  assert.equal(reloaded.sentFromHere("a"), false, "a post of an earlier page counted as sent from this one");
  assert.equal(page.sentFromHere("a"), true);
  // A removal upstream: kept no longer, here or on the device.
  reloaded.removed("b");
  assert.equal(reloaded.stands("b"), false);
  assert.deepStrictEqual(Object.keys(JSON.parse(saved.get("vibe-talk.own-posts"))).sort(), ["a", "c"]);
  // Past the grace: forgotten as it is asked, though sent from this page it still is.
  now = 1000 + OWN_POST_GRACE_MS;
  assert.equal(page.stands("a"), false);
  assert.equal(page.sentAt("a"), undefined);
  assert.equal(page.sentFromHere("a"), true);
  const late = owner();
  late.load();
  assert.deepStrictEqual([late.stands("a"), late.stands("c")], [false, true]);
  // A full quota or a damaged copy costs only the device's copy.
  full = true;
  page.noteSent(["d"]);
  assert.equal(page.stands("d"), true);
  full = false;
  saved.set("vibe-talk.own-posts", "{not json");
  const damaged = owner();
  damaged.load();
  assert.equal(damaged.stands("c"), false);
  now += OWN_POST_GRACE_MS;
  page.removed("zz");
  damaged.noteSent([]);
  assert.equal(saved.has("vibe-talk.own-posts"), false, "nothing in its grace was still saved");
});

test("`#624 voice-page-modularity`: an outbox entry read back from the device, from the module alone", () => {
  const { outgoingFromSaved, savedWire } = OUTBOX;
  let asked = 0;
  const now = () => { asked += 1; return 5000; };
  const base = { id: "e1", channel: "c", text: " hi ", createdAt: 100, state: "failed", detail: "Refused." };
  for (const bad of [null, 7, "x", {}, { ...base, id: 1 }, { ...base, channel: "" }, { ...base, text: null }, { ...base, state: "posting" }]) {
    assert.equal(outgoingFromSaved(bad, now), null, `read back as an entry: ${JSON.stringify(bad)}`);
  }
  const failed = outgoingFromSaved(base, now);
  assert.deepStrictEqual(
    [failed.state, failed.remaining, failed.originView, failed.marksRead, failed.sendStartedAt, failed.detail, failed.mayHavePosted],
    ["failed", "hi", "main", null, 100, "Refused.", false]);
  assert.equal(asked, 0, "the clock was asked where no saved time was missing");
  // The page closed mid-send: only a POST that had started may have been delivered.
  const posting = outgoingFromSaved({ ...base, state: "sending", phase: "posting", createdAt: undefined }, now);
  assert.deepStrictEqual([posting.state, posting.mayHavePosted, posting.createdAt, posting.detail],
    ["unconfirmed", true, 5000, "This page closed before delivery was confirmed."]);
  for (const phase of ["queued", "placing"]) {
    const waiting = outgoingFromSaved({ ...base, state: "sending", phase }, now);
    assert.deepStrictEqual([waiting.state, waiting.mayHavePosted, waiting.detail],
      ["failed", false, "This page closed before this message was sent."]);
  }
  // An entry saved before marksRead marks what it answers; parts and wire keep only what is whole.
  const reply = outgoingFromSaved({ ...base, state: "sent", replyTo: "r", originView: "thread",
    parts: [{ id: "p", content: "a" }, { id: 2, content: "b" }, null], observedParts: ["p", 3],
    wire: { text: "w", replyTo: "", threadId: "t" }, serverMs: "12", upstreamMs: "soon", sentAt: 9 }, now);
  assert.deepStrictEqual(
    [reply.marksRead, reply.originView, reply.parts, reply.observedParts, reply.wire, reply.serverMs, reply.upstreamMs, reply.sentAt],
    ["r", "thread", [{ id: "p", content: "a" }], ["p"], { text: "w", replyTo: null, threadId: "t" }, 12, null, 9]);
  assert.equal(outgoingFromSaved({ ...base, replyTo: "r", marksRead: null }, now).marksRead, null);
  assert.equal(savedWire({ text: 3 }), null);
});

test("`#624 voice-page-modularity`: the message boxes' drafts, saved and taken back, from the module alone", () => {
  const { createChannelDrafts } = OUTBOX;
  const saved = new Map();
  let refuse = 0;
  let roomMade = 0;
  const storage = {
    getItem: (key) => saved.get(key) ?? null,
    setItem: (key, value) => { if (refuse > 0) refuse -= 1; else saved.set(key, value); },
    removeItem: (key) => saved.delete(key),
  };
  const make = () => createChannelDrafts({ storage, makeRoom: () => { roomMade += 1; } });
  const drafts = make();
  drafts.set('["c",null]', "hello");
  drafts.set('["c","t"]', "in a thread");
  assert.equal(saved.has("vibe-talk.channel-drafts"), false, "a set wrote to the device before a save");
  assert.equal(drafts.save(), true);
  assert.deepStrictEqual(JSON.parse(saved.get("vibe-talk.channel-drafts")), { '["c",null]': "hello", '["c","t"]': "in a thread" });
  // A full quota: the saved channel rows go once, and a second refusal is reported.
  drafts.delete('["c","t"]');
  refuse = 1;
  assert.equal(drafts.save(), true);
  assert.equal(roomMade, 1);
  refuse = 2;
  drafts.set('["d",null]', "lost");
  assert.equal(drafts.save(), false);
  assert.equal(roomMade, 2);
  // Another page takes back what the device kept; anything not a string is not a draft.
  saved.set("vibe-talk.channel-drafts", JSON.stringify({ a: "kept", b: 3, c: "" }));
  const again = make();
  again.load();
  assert.deepStrictEqual([again.get("a"), again.get("b"), again.get("c")], ["kept", undefined, ""]);
  saved.set("vibe-talk.channel-drafts", "{not json");
  const damaged = make();
  damaged.load();
  assert.equal(damaged.get("a"), undefined);
});

test("`#624 voice-page-modularity`: what a send can do, and when its receipt goes, from the module alone", () => {
  const { editableSend, waitingItsTurn, unsentText, underDraft, sendSnippet, sentReceiptRetires, SENT_RECEIPT_MS, OWN_POST_GRACE_MS } = OUTBOX;
  const send = { id: "e", channel: "c", text: "all of it", parts: [], observedParts: [] };
  assert.equal(unsentText({ ...send, postedCount: 1, remaining: "the rest" }), "the rest");
  assert.equal(unsentText(send), "all of it");
  const queued = { ...send, state: "sending", phase: "queued" };
  assert.deepStrictEqual([waitingItsTurn(queued, false), waitingItsTurn(queued, true), waitingItsTurn({ ...queued, phase: "posting" }, false)],
    [true, false, false]);
  assert.deepStrictEqual([editableSend({ ...send, state: "failed" }, false), editableSend(queued, false), editableSend(queued, true)],
    [true, true, false]);
  assert.equal(editableSend({ ...send, state: "failed", mayHavePosted: true }, false), false, "a send that may have landed was editable");
  assert.equal(editableSend({ ...send, state: "unconfirmed" }, false), false);
  assert.deepStrictEqual([underDraft("draft  \n", "text"), underDraft("  ", "text"), underDraft(undefined, "text")],
    ["draft\n\ntext", "text", "text"]);
  assert.equal(sendSnippet("short  one"), "short one");
  assert.equal(sendSnippet("the quick brown fox jumps over the lazy dog"), "the quick brown fox jumps…");
  assert.equal(sendSnippet("abcdefghijklmnopqrstuvwxyz0123456789"), "abcdefghijklmnopqrstuvwxyz0…");
  // A receipt: gone once read back whole, or past the grace; where the store keeps own posts, once
  // shown long enough and every part is drawn or stored in the selected channel.
  let now = 1000;
  const view = (over = {}) => ({ now: () => now, keepsOwnPosts: () => true, selectedChannel: () => "c", storedIn: () => new Set(["p2"]), ...over });
  const sent = { ...send, state: "sent", sentAt: 1000, parts: [{ id: "p1" }, { id: "p2" }] };
  const none = new Set();
  assert.equal(sentReceiptRetires({ ...sent, state: "failed" }, none, view()), false);
  assert.equal(sentReceiptRetires({ ...sent, parts: [] }, none, view()), false);
  assert.equal(sentReceiptRetires({ ...sent, observedParts: ["p1", "p2"] }, none, view()), true);
  now = 1000 + SENT_RECEIPT_MS - 1;
  assert.equal(sentReceiptRetires(sent, new Set(["p1"]), view()), false, "a receipt went before it was shown long enough");
  now = 1000 + SENT_RECEIPT_MS;
  assert.equal(sentReceiptRetires(sent, new Set(["p1"]), view()), true);
  assert.equal(sentReceiptRetires(sent, none, view()), false, "a part neither drawn nor stored retired its receipt");
  assert.equal(sentReceiptRetires(sent, new Set(["p1"]), view({ keepsOwnPosts: () => false })), false);
  assert.equal(sentReceiptRetires(sent, new Set(["p1", "p2"]), view({ selectedChannel: () => "other" })), false);
  assert.equal(sentReceiptRetires(sent, new Set(["p1"]), view({ storedIn: () => null })), false);
  now = 1000 + OWN_POST_GRACE_MS;
  assert.equal(sentReceiptRetires(sent, none, view({ keepsOwnPosts: () => false })), true);
});

test("`#624 voice-page-modularity`: the outbox's entries, order, changes and saved copy, from the module alone", () => {
  const { createOutboxStore } = OUTBOX;
  const saved = new Map();
  let refuse = 0;
  let roomMade = 0;
  const storage = {
    getItem: (key) => saved.get(key) ?? null,
    setItem: (key, value) => { if (refuse > 0) refuse -= 1; else saved.set(key, value); },
    removeItem: (key) => saved.delete(key),
  };
  const outbox = createOutboxStore({ storage, makeRoom: () => { roomMade += 1; }, keepsOwnPosts: (channel) => channel === "threaded" });
  const a = { id: "a", channel: "flat", state: "failed", createdAt: 1 };
  const b = { id: "b", channel: "threaded", state: "sent", createdAt: 2 };
  const c = { id: "c", channel: "threaded", state: "sending", createdAt: 3 };
  outbox.add(a);
  outbox.add(c);
  outbox.add(b);
  assert.deepStrictEqual([...outbox.ids()], ["a", "c", "b"], "not in the order written");
  assert.equal(outbox.get("c"), c, "the outbox held a copy, not the page's own entry");
  assert.deepStrictEqual([outbox.has("b"), outbox.size(), outbox.version()], [true, 3, 0]);
  // A save moves the version and leaves out a confirmed send where the store keeps own posts.
  assert.equal(outbox.save(), true);
  assert.deepStrictEqual(JSON.parse(saved.get("vibe-talk.outgoing-messages")).map((entry) => entry.id), ["a", "c"]);
  assert.deepStrictEqual([outbox.version(), outbox.storageOkay()], [1, true]);
  outbox.touch();
  assert.equal(outbox.version(), 2);
  // Removing while walking passes the removed entry over; putting one back puts it where it was written.
  for (const entry of outbox.values()) if (entry.id === "a") outbox.remove("c");
  assert.deepStrictEqual([...outbox.ids()], ["a", "b"]);
  outbox.remove("a");
  outbox.putBackInOrder(a);
  outbox.putBackInOrder(c);
  assert.deepStrictEqual([...outbox.ids()], ["a", "b", "c"]);
  // A full quota gives up the saved rows once; a second refusal is reported, and remembered. (The
  // copy already there is cleared each time: a refused write that reads back the same copy stands.)
  saved.clear();
  refuse = 1;
  assert.equal(outbox.save(), true);
  assert.equal(roomMade, 1);
  saved.clear();
  refuse = 2;
  assert.equal(outbox.save(), false);
  assert.deepStrictEqual([roomMade, outbox.storageOkay()], [2, false]);
  assert.equal(outbox.save(), true);
  assert.deepStrictEqual(outbox.saved().map((entry) => entry.id), ["a", "c"]);
  outbox.refused();
  assert.equal(outbox.storageOkay(), false);
  saved.set("vibe-talk.outgoing-messages", "{not json");
  assert.throws(() => outbox.saved());
});

test("`#624 voice-page-modularity`: prepared read-aloud tickets end on either clock, from the module alone", () => {
  const { createPreparedSpeech, ticketLeftMs } = SPEECH_PIECES;
  let now = { mono: 100, wall: 5000 };
  const prepared = createPreparedSpeech({ now: () => now });
  const entry = { url: "/speech/a", until: { mono: 200, wall: 5100 }, blocks: null };
  prepared.keep("7", entry);
  assert.deepStrictEqual([prepared.has(7), prepared.size(), prepared.entry(7)], [true, 1, entry], "an id was not read as its string");
  assert.equal(ticketLeftMs(entry, now), 100);
  assert.equal(ticketLeftMs(entry, { mono: 150, wall: 5080 }), 20, "not the nearer of the two deadlines");
  // The phone slept: the monotonic clock stood still while the wall clock, and the ticket, went on.
  now = { mono: 150, wall: 5100 };
  assert.equal(prepared.entry("7"), null, "a ticket past its wall-clock deadline was played");
  assert.equal(prepared.has("7"), false, "an ended ticket was kept");
  prepared.keep("8", { ...entry, until: { mono: 150, wall: 9999 } });
  assert.equal(prepared.entry("8"), null, "a ticket past its monotonic deadline was played");
  // `get` keeps what is past its deadline; `forget` and `clear` drop it.
  prepared.keep("9", entry);
  assert.equal(prepared.get("9"), entry);
  prepared.forget("9");
  assert.equal(prepared.get(9), undefined);
  prepared.keep("10", entry);
  prepared.clear();
  assert.equal(prepared.size(), 0);
});

test("`#624 voice-page-modularity`: a Server-Sent Events stream read into frames, across chunk boundaries, from the module alone", async () => {
  const { parseEventFrame, readEventStream } = SYNC;
  assert.deepStrictEqual(parseEventFrame("id: 7\nevent: message_create\ndata: {\"a\":\ndata: 1}\r"),
    { id: "7", event: "message_create", data: '{"a":\n1}' });
  assert.deepStrictEqual(parseEventFrame(": keep-alive"), { id: null, event: "message", data: "" }, "a comment was a frame with data");
  assert.deepStrictEqual(parseEventFrame("data"), { id: null, event: "message", data: "" });
  const reading = (chunks, { stopAfter = Infinity } = {}) => {
    let read = 0;
    let cancelled = 0;
    const reader = {
      read: async () => (read < chunks.length ? { done: false, value: chunks[read++] } : { done: true }),
      cancel: () => { cancelled += 1; return Promise.reject(new Error("refused")); },
    };
    const frames = [];
    const decoder = { decode: (bytes, options) => { assert.deepStrictEqual(options, { stream: true }); return bytes; } };
    const done = readEventStream(reader, () => read <= stopAfter, (frame) => {
      frames.push(frame);
      return frame.event === "reset" ? "reset" : undefined;
    }, decoder);
    return done.then((how) => ({ how, frames, cancelled: () => cancelled }));
  };
  // A frame split across chunks waits for its blank line; a partial last frame is never handed on.
  const split = await reading(["data: one\n", "\nid: 2\nda", "ta: two\n\n: ping\n\ndata: partial"]);
  assert.deepStrictEqual(split.frames.map((frame) => [frame.id, frame.data]), [[null, "one"], ["2", "two"], [null, ""]]);
  assert.equal(split.how, "ended");
  assert.equal((await reading(["event: reset\n\n", "data: after\n\n"])).how, "reset", "a reset frame did not end the read as a reset");
  // Stopped: the reader is cancelled, its refusal swallowed, and no later frame is handed on.
  const stopped = await reading(["data: a\n\n", "data: b\n\n"], { stopAfter: 1 });
  assert.deepStrictEqual(stopped.frames.map((frame) => frame.data), ["a"]);
  assert.deepStrictEqual([stopped.how, stopped.cancelled()], ["ended", 1]);
});

test("`#624 voice-page-modularity`: which read a refresh makes, and how fresh it is, from the module alone", () => {
  const { deltaCursor, isCursorRefusal, isMutationKey, staleAsOf, STALE_AS_OF_MS, TIMELINE_RECONCILE_MS } = SYNC;
  let now = 10 * TIMELINE_RECONCILE_MS;
  const facts = (over = {}) => ({
    storeChannel: () => "c", selectedChannel: () => "c", complete: () => true, mutationAwaits: () => false, now: () => now,
    cover: () => ({ live: true, newest: "cur", fullAt: now - 1000 }), ...over,
  });
  assert.equal(deltaCursor("poll", facts()), "cur");
  assert.equal(deltaCursor("enter", facts()), null, "a reason no delta serves read a delta");
  assert.equal(deltaCursor(undefined, facts()), null);
  assert.equal(deltaCursor("poll", facts({ storeChannel: () => "other" })), null, "another channel's cursor was used");
  assert.equal(deltaCursor("poll", facts({ cover: () => ({ live: false, newest: "cur", fullAt: now }) })), null);
  assert.equal(deltaCursor("poll", facts({ cover: () => ({ live: true, newest: "cur", fullAt: now - TIMELINE_RECONCILE_MS }) })), null,
    "a view past its reconcile read a delta");
  // Edits and removals need complete deltas; a replay only while one is waiting for a read.
  assert.deepStrictEqual(["mutation", "replay", "poll", "live"].map((reason) => deltaCursor(reason, facts({ complete: () => false }))),
    [null, "cur", null, "cur"]);
  assert.equal(deltaCursor("replay", facts({ complete: () => false, mutationAwaits: () => true })), null);
  // A queued read standing for several reasons is a delta only if every one could be.
  assert.equal(deltaCursor(["poll", "live"], facts()), "cur");
  assert.equal(deltaCursor(["poll", "enter"], facts()), null);
  assert.equal(deltaCursor([], facts()), null);
  assert.deepStrictEqual([isCursorRefusal({ status: 410, code: "cursor_expired" }), isCursorRefusal({ status: 400, code: "cursor_mismatch" }),
    isCursorRefusal({ status: 410, code: "other" }), isCursorRefusal(null)], [true, true, false, false]);
  assert.deepStrictEqual([isMutationKey("message_update:1"), isMutationKey("message_delete:1"), isMutationKey("message:1")], [true, true, false]);
  // Freshness: now, unless the server says its copy is old enough to say so, or it answered from its own copy.
  const at = (ms) => new Date(ms).toISOString();
  now = Date.parse("2026-10-29T12:00:00Z");
  const clock = () => now;
  assert.equal(staleAsOf({ as_of: at(now - STALE_AS_OF_MS) }, false, clock), null);
  assert.equal(staleAsOf({ as_of: at(now - STALE_AS_OF_MS - 1000) }, false, clock), now - STALE_AS_OF_MS - 1000);
  assert.equal(staleAsOf({}, false, clock), null);
  assert.equal(staleAsOf({ as_of: at(now - 5000) }, true, clock), now - 5000, "a stand-in copy was taken for a current one");
  assert.equal(staleAsOf({ as_of: at(now + 5000) }, true, clock), now, "a stand-in copy dated ahead claimed to be newer than now");
  assert.equal(staleAsOf(null, true, clock), now);
});

test("`#624 voice-page-modularity`: the browser's socket, audio, microphone and device-voice ports look each global up when used, not when made", async () => {
  const names = ["WebSocket", "Audio", "window", "navigator"];
  const saved = names.map((name) => [name, Object.getOwnPropertyDescriptor(globalThis, name)]);
  const put = (name, value) => Object.defineProperty(globalThis, name, { value, configurable: true, writable: true });
  try {
    const ports = WEB_PLATFORM.createWebPorts();
    // Installed after the ports were made: a stand-in a test (or a browser walk) puts in late is used.
    put("WebSocket", class { constructor(url) { this.url = url; } });
    put("Audio", class { constructor(url) { this.src = url; } });
    class Prefixed {}
    put("window", { webkitAudioContext: Prefixed });
    const asked = [];
    put("navigator", { mediaDevices: { getUserMedia(constraints) { asked.push([this === globalThis.navigator.mediaDevices, constraints]); return Promise.resolve("stream"); } } });
    assert.equal(ports.socket.open("wss://voice/a").url, "wss://voice/a");
    assert.equal(ports.audio.element("/speech/1").src, "/speech/1");
    assert.equal(ports.audio.contextClass(), Prefixed, "WebKit's prefixed context was not the fallback");
    class Unprefixed {}
    put("window", { AudioContext: Unprefixed, webkitAudioContext: Prefixed });
    assert.equal(ports.audio.contextClass(), Unprefixed);
    put("window", {});
    assert.equal(ports.audio.contextClass(), undefined);
    assert.equal(await ports.microphone.open({ audio: true }), "stream");
    assert.deepStrictEqual(asked, [[true, { audio: true }]], "getUserMedia was not called on mediaDevices, with the constraints given");
    // The device's voice: an engine only where it can list voices, speak and cancel, and utterances exist.
    const engine = { getVoices() {}, speak() {}, cancel() {} };
    class Utterance { constructor(text) { this.text = text; } }
    put("window", { speechSynthesis: engine, SpeechSynthesisUtterance: Utterance });
    assert.equal(ports.speech.engine(), engine);
    assert.equal(ports.speech.utterance("hello").text, "hello");
    put("window", { speechSynthesis: { getVoices() {}, speak() {} }, SpeechSynthesisUtterance: Utterance });
    assert.equal(ports.speech.engine(), null, "an engine that cannot cancel was used");
    put("window", { speechSynthesis: engine });
    assert.equal(ports.speech.engine(), null, "an engine with no utterances was used");
    put("window", {});
    assert.equal(ports.speech.engine(), null);
  } finally {
    for (const [name, descriptor] of saved) {
      if (descriptor) Object.defineProperty(globalThis, name, descriptor);
      else delete globalThis[name];
    }
  }
});

test("`#624 voice-page-modularity`: when a cut-off read tries again, and when a ticket can no longer carry it, from the module alone", () => {
  const { recoveryWait, ticketEnded, ticketTooShortForBlocks, READ_RECOVERY_WAITS_MS, BLOCK_READ_TICKET_MARGIN_MS } = SPEECH_PIECES;
  assert.deepStrictEqual(READ_RECOVERY_WAITS_MS.map((_, at) => recoveryWait(at)), READ_RECOVERY_WAITS_MS);
  assert.equal(recoveryWait(READ_RECOVERY_WAITS_MS.length), null, "a read tried again after its last try");
  const ticket = { until: { mono: 100, wall: 1000 } };
  assert.deepStrictEqual([ticketEnded(ticket, { mono: 99, wall: 999 }), ticketEnded(ticket, { mono: 100, wall: 0 }), ticketEnded(ticket, { mono: 0, wall: 1000 })],
    [false, true, true]);
  const entry = { url: "/u", until: { mono: BLOCK_READ_TICKET_MARGIN_MS, wall: 10 * BLOCK_READ_TICKET_MARGIN_MS }, blocks: null };
  assert.equal(ticketTooShortForBlocks(entry, { mono: 0, wall: 0 }), false);
  assert.equal(ticketTooShortForBlocks(entry, { mono: 1, wall: 0 }), true, "a ticket with less than the margin left started a read in blocks");
});

test("`#624 voice-page-modularity`: when a call reconnects after a lost turn, and when it ends, from the module alone", () => {
  const { reconnectAsked, reconnectVerdict, LOST_TURN, RECONNECT_MIN_GAP_MS, RECONNECTS_PER_CALL_MAX } = CALL;
  const call = { protocol: "vibe-talk-v1", v1Ready: true, reconnects: 0, lastReconnectAt: 0 };
  const said = "turn 4 never started; reconnect.";
  assert.equal(reconnectAsked(call, said), true);
  assert.equal(reconnectAsked(call, "turn 4 never started"), false, "an error that did not ask reconnected");
  assert.equal(reconnectAsked({ ...call, v1Ready: false }, said), false, "a session that never started reconnected");
  assert.equal(reconnectAsked({ ...call, protocol: "elevenlabs" }, said), false, "the hosted vendor's protocol reconnected");
  assert.equal(LOST_TURN.exec(said)[1], "4");
  assert.equal(reconnectVerdict(call, 1000), "reconnect");
  assert.equal(reconnectVerdict({ ...call, reconnects: 1, lastReconnectAt: 1000 }, 1000 + RECONNECT_MIN_GAP_MS - 1), "soon");
  assert.equal(reconnectVerdict({ ...call, reconnects: 1, lastReconnectAt: 1000 }, 1000 + RECONNECT_MIN_GAP_MS), "reconnect");
  assert.equal(reconnectVerdict({ ...call, reconnects: RECONNECTS_PER_CALL_MAX, lastReconnectAt: 0 }, 1e9), "count");
});

test("`#624 voice-page-modularity`: what a call's seams and the line under it say of its recap, from the module alone", () => {
  const { boundaryFor, callRecapLine, recapChip, recapWords, seamDetailFor, reconnectFreshWords, STORED_SEAM_DETAIL } = CALL;
  const fresh = (why) => `the page's reason for ${why}`;
  const sent = { state: "sent", words: 1234, lines: 9, dropped: 2, transport: "replay" };
  assert.deepStrictEqual([recapWords(sent), recapWords({ ...sent, words: 0 }), recapWords({ state: "sent" })], [1234, null, null]);
  assert.deepStrictEqual([recapChip(sent), recapChip({ state: "none", why: "off" }), recapChip({ state: "none", why: "refused" })],
    ["1,234-word recap sent", null, "recap refused"]);
  assert.equal(callRecapLine(sent, "accepted", fresh), "Caught the agent up with 1,234 words from earlier; 2 older lines did not fit");
  assert.equal(callRecapLine({ ...sent, transport: "profile", dropped: 0 }, "waiting", fresh), "Handing the agent 1,234 words from earlier");
  assert.equal(callRecapLine({ state: "none", why: "empty" }, null, fresh), "Started fresh: nothing was said aloud earlier");
  assert.equal(callRecapLine({ state: "none", why: "unsupported" }, null, fresh), "Started fresh: the page's reason for unsupported");
  assert.equal(callRecapLine({ state: "none", why: "empty", reconnected: true }, null, fresh),
    "Reconnected after a lost turn: started fresh, as nothing said in this call was recorded to send");
  assert.equal(reconnectFreshWords("too_long"), "the earlier conversation was too long to send", "the reconnect table lost the call table's reasons");
  // A seam: the resuming wording only where a recap went; the stored record's sentence with no cause.
  assert.notEqual(seamDetailFor("closed", true), seamDetailFor("closed", false));
  assert.equal(seamDetailFor("no such cause", false), seamDetailFor("ended", false));
  assert.equal(boundaryFor(null, null).detail, STORED_SEAM_DETAIL);
  assert.equal(boundaryFor(sent, null).detail, seamDetailFor("ended", true));
  assert.equal(boundaryFor({ state: "none", why: "replaced_session" }, null).detail, seamDetailFor("replaced", false));
  assert.equal(boundaryFor({ state: "none", why: "empty" }, "closed").detail, seamDetailFor("closed", false));
});

test("`#624 voice-page-modularity`: what a reconnect and a draft's fate say in the transcript, from the module alone", () => {
  const { reconnectSeamDetail, notSentDetail, spokenOutcomeKind, spokenYesSeam } = CALL;
  assert.match(reconnectSeamDetail("recap", "typed"), /sent this call's record, and your message went again/);
  assert.match(reconnectSeamDetail("fresh", "none"), /has seen nothing above this line/);
  assert.equal(reconnectSeamDetail("fresh", "nothing"), undefined, "a pair no sentence names was given one");
  assert.match(notSentDetail("withdrawn"), /^You tapped Don't send/);
  assert.equal(notSentDetail("declined"), spokenYesSeam("declined").detail, "a spoken no did not say what the spoken yes's table says");
  assert.equal(notSentDetail("something new"), notSentDetail("lapsed"));
  assert.deepStrictEqual([spokenOutcomeKind("refused"), spokenOutcomeKind("mystery")], ["refused", "not_armed"]);
  assert.equal(spokenYesSeam("sent").label, "Sent by voice");
  assert.match(spokenYesSeam("gone").detail, /no draft was waiting/);
});

// --- the requests module, on its own ports (`#624 voice-page-modularity`) -----------------------

/**
 * web/src/core/api on ports and dependencies a test supplies: every request it sends, every timer
 * it sets, every cancellation it makes, and every call it makes back into the page, recorded.
 * `answers` is what the transport does with each request in turn: a `{status, text}` answer, or an
 * Error to fail to reach the server with.
 */
function apiOnPorts(answers = []) {
  const record = { sent: [], timers: [], cleared: [], cancellations: [], refused: 0, asked: [] };
  const ports = {
    http: {
      fetch: async (path, init) => {
        record.sent.push({ path, init });
        const answer = answers.shift() ?? { status: 200, text: "{}" };
        if (answer instanceof Error) throw answer;
        return { status: answer.status, ok: answer.status >= 200 && answer.status < 300, text: async () => answer.text };
      },
    },
    clock: {
      setTimeout: (run, ms) => { record.timers.push({ run, ms }); return record.timers.length; },
      clearTimeout: (handle) => { record.cleared.push(handle); },
    },
    cancellation: {
      create: () => {
        const cancellation = { signal: { aborted: false }, abort() { this.signal.aborted = true; } };
        record.cancellations.push(cancellation);
        return cancellation;
      },
    },
  };
  const server = SERVER_API.createApi(ports, {
    token: () => "tok",
    readRefused: () => { record.refused += 1; },
    asking: (type) => { record.asked.push({ type, sentBefore: record.sent.length }); },
    answerer: () => "Discord",
  });
  return { server, record };
}

test("`#624 voice-page-modularity`: the requests module sends through its transport port, with the token, and a body only when there is one", async () => {
  const { server, record } = apiOnPorts([{ status: 200, text: '{"a":1}' }, { status: 200, text: "" }]);
  assert.deepStrictEqual(await server.request("/api/v1/x"), { a: 1 });
  assert.equal(await server.request("/api/v1/y", { method: "POST", body: { b: 2 } }), null, "an empty answer is null");
  assert.deepStrictEqual(record.sent.map((s) => s.path), ["/api/v1/x", "/api/v1/y"]);
  assert.deepStrictEqual(record.sent[0].init, { method: "GET", headers: { Authorization: "Bearer tok" } },
    "a GET says it carries JSON, or carries a signal it was not given");
  assert.deepStrictEqual(record.sent[1].init,
    { method: "POST", headers: { Authorization: "Bearer tok", "Content-Type": "application/json" }, body: '{"b":2}' });
});

test("`#624 voice-page-modularity`: the requests module keeps the error taxonomy, and ends the device's copy only on a refused token or read", async () => {
  const refusal = (status) => ({ status, text: JSON.stringify({ error: "nope", detail: "Not yours." }) });
  for (const [status, method, refused] of [[401, "POST", 1], [403, "GET", 1], [403, "POST", 0], [500, "GET", 0]]) {
    const { server, record } = apiOnPorts([refusal(status)]);
    const error = await server.request("/api/v1/x", { method }).then(() => null, (e) => e);
    assert.ok(error, `HTTP ${status} to a ${method} succeeded`);
    assert.equal(error.message, `HTTP ${status} nope: Not yours.`);
    assert.deepStrictEqual([error.status, error.code, error.detail, error.refused],
      [status, "nope", "Not yours.", status === 401 || status === 403]);
    assert.deepStrictEqual(error.body, { error: "nope", detail: "Not yours." });
    assert.equal(record.refused, refused, `HTTP ${status} to a ${method}: the page's copy was dropped ${record.refused} times`);
  }
  // Not this server speaking: a proxy's page, a gateway's JSON, the network.
  const proxy = await apiOnPorts([{ status: 502, text: "<html>" }]).server.request("/x").catch((e) => e);
  assert.deepStrictEqual([proxy.message, proxy.gatewayStatus], ["vibe-talk returned non-JSON (HTTP 502)", 502]);
  const garbled = await apiOnPorts([{ status: 200, text: "<html>" }]).server.request("/x").catch((e) => e);
  assert.equal(garbled.gatewayStatus, undefined, "a garbled success was worded as a gateway's failure");
  const gateway = await apiOnPorts([{ status: 504, text: '{"message":"x"}' }]).server.request("/x").catch((e) => e);
  assert.deepStrictEqual([gateway.message, gateway.code], ["HTTP 504 error: (no detail)", "error"]);
  const unreachable = await apiOnPorts([new TypeError("Failed to fetch")]).server
    .request("/x", { method: "PUT" }).catch((e) => e);
  assert.equal(unreachable.network, true);
  assert.match(unreachable.message, /^Could not reach vibe-talk while saving your change\./);
  assert.equal(unreachable.cause.message, "Failed to fetch");
});

test("`#624 voice-page-modularity`: a decoded request is told to the page before it is sent, and a malformed answer names the type", async () => {
  const { server, record } = apiOnPorts([{ status: 200, text: '{"nope":true}' }]);
  const error = await server.decoded("ApiErrorBody", "/x").catch((e) => e);
  assert.deepStrictEqual(record.asked, [{ type: "ApiErrorBody", sentBefore: 0 }]);
  assert.equal(record.sent.length, 1, "the decoded request was told to the page but never sent");
  assert.match(error.message, /^vibe-talk returned a malformed answer — .*ApiErrorBody/);
  assert.ok(error.cause, "the contract's own sentence was dropped");
});

test("`#624 voice-page-modularity`: a request given up on by `within` times out on the clock port, aborted unless the caller keeps it", async () => {
  // Aborted: the one cancellation made, its signal handed to the request, and aborted at the limit.
  const { server, record } = apiOnPorts();
  let signal = null;
  const waited = server.within(20_000, (s) => { signal = s; return new Promise(() => {}); }).catch((e) => e);
  assert.equal(record.timers.length, 1);
  assert.equal(record.timers[0].ms, 20_000);
  assert.equal(signal, record.cancellations[0].signal, "the request was not handed the cancellation's signal");
  record.timers[0].run();
  const error = await waited;
  assert.deepStrictEqual([error.message, error.timedOut], ["Discord did not answer within 20 seconds.", true]);
  assert.equal(signal.aborted, true, "the request given up on was not aborted");
  assert.deepStrictEqual(record.cleared, [1], "the timer was not cleared");
  // Kept: no cancellation at all, and the request still on the wire handed back.
  const kept = apiOnPorts();
  const still = new Promise(() => {});
  let handed = null;
  const keptWait = kept.server.within(1_500, (s) => { assert.equal(s, undefined); return still; }, (answer) => { handed = answer; })
    .catch((e) => e);
  kept.record.timers[0].run();
  assert.match((await keptWait).message, /within 2 seconds/);
  assert.equal(handed, still, "the request still on the wire was not handed to the caller");
  assert.equal(kept.record.cancellations.length, 0, "a request the caller keeps was given a cancellation");
  // Answered in time: the answer, and the timer cleared.
  const quick = apiOnPorts();
  assert.equal(await quick.server.within(5_000, async () => "ok"), "ok");
  assert.deepStrictEqual(quick.record.cleared, [1]);
});

test("`#624 voice-page-modularity`: a failed request in words, from the requests module alone", () => {
  const { readableFailure, isSlowFailure, providerWords } = SERVER_API;
  assert.equal(providerWords('Slack returned HTTP 502: {"message":"upstream timed out"}'), "upstream timed out");
  assert.equal(providerWords('X returned HTTP 502: {"message":"cut sho'), "X returned HTTP 502");
  assert.equal(providerWords('X: {"detail":"half \\"quoted\\" words","more'), 'half "quoted" words');
  assert.equal(isSlowFailure({ status: 502, detail: "deadline exceeded" }), true);
  assert.equal(isSlowFailure({ status: 400, detail: "deadline exceeded" }), false);
  assert.equal(readableFailure({ status: 504 }, "discord"), "Discord is slow to answer right now.");
  assert.equal(readableFailure({ status: 502, detail: "" }, "slack"), "Slack could not answer (HTTP 502).");
  assert.equal(readableFailure({ status: 409, message: "HTTP 409 moved: x" }, "slack"), "HTTP 409 moved: x",
    "a refusal below 500 is the server's own sentence");
  assert.equal(readableFailure(null, "slack"), "");
});

