  assert.deepStrictEqual(JSON.parse(socket.sent.at(-1)), { type: "prompt", text: "anyone there" });
  assert.equal(page.expireTimers(NO_REPLY_MS), 1, "the typed prompt was given no bound");
  await page.settle();
