  for (const selector of ["#post-confirm-title", "#post-confirm-where", "#post-confirm-expiry", ".sent-how"]) {
    assert.match(cssBlock(selector), /color:\s*var\(--muted-on-mine\)/, `${selector} is drawn in --muted on the tile`);
  }
