/** `bigCardData`'s big root, its record naming its thread as a page of Main brings it. */
const NAMED = { display_name: "cache-tier-deploy", summary: "The cache tier deploy, pool by pool." };

test("`#528 thread-card-markdown-and-cap`: a root's own record names its thread, so its card says the summary from Main's read, and from the device's copy on a reload", async () => {
  const data = bigCardData();
  data.messages[0] = { ...data.messages[0], thread: { ...data.messages[0].thread, ...NAMED } };
  const page = newPage(new Map());
  page.threadingSupported = true;
  // The thread list knows nothing of the thread yet: what names it is the root's record alone.
  page.threads = [data.threads[1]];
  page.messages = data.messages;
  forwardTimeline(page);
  await signIn(page);
  await showDiscord(page, data.messages);
  await pickThread(page, "threads");
  await page.settle();
  const summary = `${NAMED.display_name}: ${NAMED.summary}`;
  assert.equal(cardPart(page, BIG, "side-card-text"), summary, "the root's record did not name its card");
  assert.ok(cardRow(page, BIG).hasAttribute("data-summarised-card"));
  // A copy of the root from the stream names nothing (only a page's copy does): it keeps the name.
  const edited = { ...data.messages[0], content: `${BIG_ROOT}\n8. celebrate`, edited_timestamp: data.messages[1].timestamp,
    thread: { ...data.messages[0].thread } };
  delete edited.thread.display_name;
  delete edited.thread.summary;
  await deliver(page, page.stream(), sseUpdate("upd-528", edited));
  await page.settle();
  assert.equal(cardPart(page, BIG, "side-card-text"), summary, "the stream's copy took the thread's name away");
  // Reloaded, before any read answers: the device's copy draws the summary card at once.
  const again = reloadWith(new Map(page.storage), data.messages, (p) => {
    p.threadingSupported = true;
    p.threads = [];
    p.timeline = () => new Promise(() => {});
  });
  await signIn(again);
  await again.settle();
  assert.equal(again.el("thread-select").value, "threads", "the premise: the reload reopens the Threads view");
  assert.equal(cardPart(again, BIG, "side-card-text"), summary, "the reload did not draw the saved summary at once");
});

/** `bigCardPage` with the server naming threads, the clock a second after the big thread's reply. */
async function pendingCardPage(storage = new Map([[UNPACK_STORAGE, "all"]]), content = BIG_ROOT) {
  const data = bigCardData();
  data.messages[0].content = content;
  const page = newPage(storage);
  page.threadingSupported = true;
  page.threadNamesSupported = true;
  page.setClock(Date.parse(data.threads[0].updated_at) + 1000);
  page.threads = data.threads;
  page.messages = data.messages;
  const server = forwardTimeline(page);
  await signIn(page);
  await showDiscord(page, data.messages);
  await pickThread(page, "threads");
  await page.settle();
  return { page, server, data };
}

test("`#528 thread-card-markdown-and-cap`: a summary on its way is waited for in the summary's layout, read for at once, and only the card's words change when it lands", async () => {
  const { page, server } = await pendingCardPage();
  const row = cardRow(page, BIG);
  assert.ok(row.hasAttribute("data-summary-pending"), "a long root's card with a reply does not wait for its summary");
  assert.ok(!row.hasAttribute("data-split-card"), "a card waiting for its summary is split");
  const head = BIG_ROOT.split("\n").slice(0, 5);
  assert.deepStrictEqual(cardLinesOf(page, BIG), [...head.slice(0, 4), `${head[4]}…`]);
  // The root is inward whole at once, as it will stay under the summary.
  const ids = () => unpackRows(page, BIG).map((li) => li.getAttribute("data-ids"));
  assert.deepStrictEqual(ids(), ["800", "801"]);
  const [root] = unpackRows(page, BIG);
  assert.ok(root.hasAttribute("data-root-child") && !root.hasAttribute("data-root-continuation"),
    "the root is not inward whole while its summary is on its way");
  assert.match(bodyOf(root).text(), /^Deploy plan for the cache tier/);
  // The Threads list is read again within seconds, though it was read under a minute ago.
  const from = page.timelineCalls.length;
  await passTime(page, 2500);
  assert.ok(readViewsSince(page, from).includes("threads"), `the thread list was not read again soon: ${readViewsSince(page, from)}`);
  // The server names it; the next step's read brings it; the card says it and nothing under it moves.
  Object.assign(page.threads[0], NAMED);
  server.threadChanged.set(BIG, ++server.revision);
  await passTime(page, 3000);
  assert.equal(cardPart(page, BIG, "side-card-text"), `${NAMED.display_name}: ${NAMED.summary}`, "the summary did not land");
  assert.ok(!cardRow(page, BIG).hasAttribute("data-summary-pending"));
  assert.deepStrictEqual(ids(), ["800", "801"], "the rows under the card changed as the summary landed");
  assert.ok(unpackRows(page, BIG)[0].hasAttribute("data-root-child"));
});

test("`#528 thread-card-markdown-and-cap`: a summary that does not come within its wait is not waited for: the card splits", async () => {
  const { page } = await pendingCardPage();
  assert.ok(cardRow(page, BIG).hasAttribute("data-summary-pending"), "the premise: waiting for a summary");
  await passTime(page, sourceConstant("SUMMARY_WAIT_MS"));
  assert.ok(!cardRow(page, BIG).hasAttribute("data-summary-pending"), "the card waited past its wait");
  assert.ok(cardRow(page, BIG).hasAttribute("data-split-card"), "the card did not split when its summary did not come");
  assert.ok(unpackRows(page, BIG)[0].hasAttribute("data-root-continuation"));
  // Nor does a thread whose last activity is older than the wait wait at all, nor one with no reply.
  const old = await pendingCardPage();
  old.page.setClock(old.page.clock() + sourceConstant("SUMMARY_WAIT_MS"));
  assert.equal(old.page.pure("cardPending")(old.page.pure("threadChoices")().find((one) => one.id === BIG)), false);
  // Waiting with a first paragraph longer than K, the card is clamped to K as a clamped card is.
  const words = Array.from({ length: 61 }, (_, at) => `w${String(at).padStart(3, "0")}`).join(" ");
  const long = await pendingCardPage(undefined, words);
  const row = cardRow(long.page, BIG);
  assert.ok(row.hasAttribute("data-summary-pending") && row.hasAttribute("data-card-clamp"),
    "a waiting card whose first paragraph is longer than K is not clamped");
});

// --- an unpacked row is a message row like any other (#407 unpack-row-parity) ---------------------------
//
// The owner, 2026-10-21, after trying #404: "When I mouse over the unpacked messages they do not
// highlight. I can click to collapse expand but not use a keystroke on the highlighted one. Keystroke
// ':' does not work to expand/collapse all. I don't want us to have separate code." So an unpacked row
// answers the mouse, the selection, every key about one message, ; and :, and the read modes exactly as
// a row of Main, All or a thread does, through the same code: these press the same keys on both.

/** `unpackData` with every message long enough to fold, and, with `collide`, thread ids that are their roots' ids. */
function parityData({ long = true, collide = false } = {}) {
  const data = unpackData();
  const ids = collide ? { "spaces/A/threads/sum": "700", "spaces/A/threads/raw": "704" } : {};
  const renamed = (id) => ids[id] || id;
  const messages = data.messages.map((one) => ({ ...one,
    content: long ? longMessage(`message ${one.id}`) : one.content,
    thread: { ...one.thread, id: renamed(one.thread.id) } }));
  const threads = data.threads.map((one) => ({ ...one, id: renamed(one.id),
    root: messages.find((m) => m.id === one.root.id) }));
  return { messages, threads };
}

async function parityPage({ read = ["700", "701", "702", "704", "705", "706"], ...options } = {}) {
  const data = parityData(options);
  const page = newPage(new Map([[UNPACK_STORAGE, "on"]]));
  page.threadingSupported = true;
  page.threads = data.threads;
  page.messages = data.messages;
  forwardTimeline(page);
  for (const id of read) page.dealtWith.add(id);
  await signIn(page);
  await showDiscord(page, data.messages);
  await pickThread(page, "threads");
  await page.settle();
  return { page, data };
}

/** The unpacked row standing for message `id` in the Threads view. */
const unpackedRow = (page, id) => page.el("side-cards").children.find((li) =>
  li.hasAttribute("data-unpack-thread") && (li.getAttribute("data-ids") || "").split(" ").includes(id));

/** The mouse moved over `row` of the Threads view, scrolled first to the top of the list's screen. */
async function mouseOnto(page, row) {
  const area = page.el("side-scroll");
  area.scrollTop += row.getBoundingClientRect().top;
  const box = row.getBoundingClientRect();
  await mouseTo(page, row, 300, box.top + 5);
}

/** What holds the focus, as `card:<thread>` for a card and the first message id for a message row. */
const heldRow = (page) => {
  const held = focused(page);
  if (!held || !held.getAttribute) return focusName(page);
  if (held.hasAttribute && held.hasAttribute("data-card")) return `card:${held.getAttribute("data-id")}`;
  return held.getAttribute("data-id") !== null ? held.getAttribute("data-id") : focusName(page);
};

test("`#407 unpack-row-parity`: the mouse over an unpacked row lights it as it lights a row of Main, and nothing else is lit", async () => {
  const { page } = await parityPage({ long: false });
  const row = unpackedRow(page, "703");
  assert.ok(row, "the fixture did not unpack 703 under its card");
  await mouseOnto(page, row);
  assert.deepStrictEqual(litRows(page), ["side-cards:703"], `the mouse over 703 lit ${JSON.stringify(litRows(page))}`);
  assert.equal(row.getAttribute("tabindex"), "0", "the row the mouse chose is not the selection's Tab stop");
  // Onto another unpacked row, of the other thread: the selection follows, one row lit.
  await mouseOnto(page, unpackedRow(page, "707"));
  assert.deepStrictEqual(litRows(page), ["side-cards:707"]);
  // And onto a card, which the mouse lit before as well: the same selection.
  await mouseOnto(page, cardRow(page, "spaces/A/threads/raw"));
  assert.deepStrictEqual(litRows(page), ["side-cards:spaces/A/threads/raw"]);
});

test("`#407 unpack-row-parity`: ↓ and ↑ (and j and k) walk cards and unpacked rows in reading order, one selection", async () => {
  const { page } = await parityPage({ long: false });
  const area = page.el("side-scroll");
  area.focus();
  await mouseOnto(page, cardRow(page, "spaces/A/threads/sum"));
  const walk = [];
  for (let step = 0; step < 6; step += 1) {
    await pressHere(page, step % 2 ? "j" : "ArrowDown");
    walk.push(heldRow(page));
  }
  assert.deepStrictEqual(walk, ["700", "701", "702", "703", "card:spaces/A/threads/raw", "705"],
    "↓ and j did not go through the unpacked rows in reading order");
  assert.deepStrictEqual(litRows(page), ["side-cards:705"], "more than the selection is lit");
  await pressHere(page, "ArrowUp");
  assert.equal(heldRow(page), "card:spaces/A/threads/raw", "↑ did not come back from an unpacked row to its card");
  await pressHere(page, "k");
  assert.equal(heldRow(page), "703", "k did not go up from a card into the block above it");
});

test("`#407 unpack-row-parity`: a thread whose id is its root's id: the root child selected is the row lit, not its card", async () => {
  const { page } = await parityPage({ long: false, collide: true });
  assert.ok(cardRow(page, "700") && unpackedRow(page, "700"), "the fixture has no card and root child sharing an id");
  page.el("side-scroll").focus();
  await mouseOnto(page, unpackedRow(page, "700"));
  assert.deepStrictEqual(litRows(page), ["side-cards:700"]);
  assert.equal(page.el("side-cards").children.find((li) => li.getAttribute("data-selected") === "true"),
    unpackedRow(page, "700"), "the root child's selection lit its card");
  await pressHere(page, "ArrowDown");
  assert.equal(heldRow(page), "701", "↓ from the root child did not go on to its first reply");
  await pressHere(page, "ArrowUp");
  assert.equal(focused(page), unpackedRow(page, "700"), "↑ went back to the card, not the root child");
  await pressHere(page, "ArrowUp");
  assert.equal(heldRow(page), "card:700", "↑ from the root child did not reach its card");
});

test("`#407 unpack-row-parity`: Enter and o fold the selected unpacked row, e marks it Done, r replies to it, as on Main", async () => {
  const { page } = await parityPage();
  const area = page.el("side-scroll");
  area.focus();
  await mouseOnto(page, unpackedRow(page, "703"));
  assert.equal(unpackedRow(page, "703").getAttribute("data-collapsed"), "true", "the fixture's 703 is not folded");
  await pressHere(page, "Enter");
  assert.equal(unpackedRow(page, "703").getAttribute("data-collapsed"), "false", "Enter did not open the selected unpacked row");
  await pressHere(page, "o");
  assert.equal(unpackedRow(page, "703").getAttribute("data-collapsed"), "true", "o did not fold it again");
  await pressHere(page, "e");
  assert.deepStrictEqual(page.dismissCalls.at(-1), { messages: ["703"] }, "e did not mark the selected unpacked row Done");
  await page.settle();
  assert.equal(unpackedRow(page, "703").getAttribute("data-archived"), "true", "the Done row is not drawn read");
  // e again on the same row puts it back, as the row's own button would: the row's read state is the one acted on.
  await mouseOnto(page, unpackedRow(page, "707"));
  await mouseOnto(page, unpackedRow(page, "703"));
  await pressHere(page, "e");
  await page.settle();
  assert.equal(unpackedRow(page, "703").getAttribute("data-archived"), "false", "e on a Done unpacked row did not put it back");
  await mouseOnto(page, unpackedRow(page, "707"));
  await pressHere(page, "r");
  assert.ok(replyInStream(page), "r did not reply to the selected unpacked row");
  assert.match(page.el("reply-target-meta").textContent, /id 707$/, "r answered another message");
});

// --- `#532 shift-o-latency` -----------------------------------------------------------------------
//
// The owner, 2026-10-26: Shift+O "does take a couple seconds. If I am folding up 4 messages in a row in a
// thread I thought I could spam the key four times and see them responsively fold up", and of e: "one of
// those things that I most want to be instantly responsive locally". Each press drew every thread
// unpacked in the Threads view again, three times over. Now a fold or a Done is drawn on the rows already
// there: the thread's card counts again in place, its rows are dressed again and its runs placed again,
// and every other thread is left alone.

/** `SHIFT_O_THREADS` threads of a root and `SHIFT_O_REPLIES` long replies, every message unread. */
const SHIFT_O_THREADS = 12;
const SHIFT_O_REPLIES = 5;
function shiftOData() {
  const messages = [];
  const threads = [];
  for (let t = 0; t < SHIFT_O_THREADS; t += 1) {
    const id = `spaces/A/threads/s${t}`;
    const rootId = String(9532000 + t * 10);
    const record = { id, root_message_id: rootId, is_root: true, reply_count: SHIFT_O_REPLIES, reply_count_exact: true };
    const root = message({ id: rootId, content: `thread ${t} root`, thread: record });
    messages.push(root);
    for (let r = 1; r <= SHIFT_O_REPLIES; r += 1) {
      messages.push(message({ id: String(9532000 + t * 10 + r), content: longMessage(`thread ${t} reply ${r}`),
        thread: { ...record, is_root: false } }));
    }
    threads.push({ id, root, title: "Thread", reply_count: SHIFT_O_REPLIES, reply_count_exact: true,
      updated_at: messages.at(-1).timestamp });
  }
  return { messages, threads };
}

async function shiftOPage(script = SCRIPT) {
  const data = shiftOData();
  const page = newPage(new Map([[UNPACK_STORAGE, "on"]]), script);
  page.threadingSupported = true;
  page.threads = data.threads;
  page.messages = data.messages;
  forwardTimeline(page);
  await signIn(page);
  await showDiscord(page, data.messages);
  await pickThread(page, "threads");
  await page.settle();
  return page;
}

/** Per-press budget in this fixture, which lays nothing out: a press that draws more than its own rows misses it. */
const SHIFT_O_BUDGET_MS = 50;

/**
 * Press `key` `times` times on whatever holds the focus, each press timed and the elements it built
 * counted, and the Threads view's rows of every other thread compared before and after.
 */
async function pressesInPlace(page, key, fields, times, own) {
  const others = () => page.el("side-cards").children.filter((li) => li.getAttribute("data-unpack-thread") !== own &&
    !(li.hasAttribute("data-card") && li.getAttribute("data-id") === own));
  const before = others();
  const took = [];
  let built = 0;
  for (let at = 0; at < times; at += 1) {
    const made = page.createdTags.length;
    const start = performance.now();
    await pressHere(page, key, fields);
    took.push(performance.now() - start);
    built += builtSince(page, made, "li");
  }
  const after = others();
  const kept = after.length === before.length && after.every((li, at) => li === before[at]);
  return { took, built, kept };
}

test("`#532 shift-o-latency`: four Shift+O and four e in an unpacked Threads view each draw in place, within budget, and the folds, Dones and Undo are right", async () => {
  const page = await shiftOPage();
  const own = "spaces/A/threads/s11";
  const rows = () => unpackRows(page, own);
  assert.equal(rows().length, SHIFT_O_REPLIES, "the premise is the last thread's replies unpacked under its card");
  const drawn = rows();
  await mouseOnto(page, unpackedRow(page, "9532115"));
  const folds = await pressesInPlace(page, "O", { shiftKey: true }, 4, own);
  assert.equal(folds.built, 0, `Shift+O built ${folds.built} rows: it drew the list again rather than fold in place`);
  assert.ok(folds.kept, "Shift+O drew the other threads again");
  assert.ok(rows().every((li, at) => li === drawn[at]), "Shift+O drew its own thread's rows again");
  assert.deepStrictEqual(rows().map((li) => li.getAttribute("data-read-run")), [null, "head", "member", "member", "member"],
    "four presses did not fold the four last replies into one line");
  assert.equal(readRunLineOf(rows()[1]).textContent, "… 4 read messages …");
  assert.equal(selectedId(page), "9532111", "the selection did not step above the folds");
  assert.deepStrictEqual(page.dismissCalls.map((call) => call.messages),
    [["9532115"], ["9532114"], ["9532113"], ["9532112"]], "each fold did not mark its message read");
  for (const li of rows().slice(1)) assert.equal(li.getAttribute("data-archived"), "true", "a folded row is not drawn read");
  assert.ok(folds.took.every((ms) => ms < SHIFT_O_BUDGET_MS),
    `a Shift+O took over ${SHIFT_O_BUDGET_MS} ms: ${folds.took.map((ms) => ms.toFixed(1)).join(", ")}`);

  // e down another thread: each Done drawn on its row, the card's unread counted again in place.
  const other = "spaces/A/threads/s10";
  const card = cardRow(page, other);
  const theirs = unpackRows(page, other);
  await mouseOnto(page, unpackedRow(page, "9532101"));
  const dones = await pressesInPlace(page, "e", {}, 4, other);
  assert.equal(dones.built, 0, `e built ${dones.built} rows: it drew the list again rather than the Done in place`);
  assert.ok(unpackRows(page, other).every((li, at) => li === theirs[at]), "e drew its thread's rows again");
  assert.equal(cardRow(page, other), card, "e drew the thread's card again rather than count it in place");
  assert.deepStrictEqual(page.dismissCalls.slice(4).map((call) => call.messages),
    [["9532101"], ["9532102"], ["9532103"], ["9532104"]], "e did not mark four messages Done, stepping down");
  assert.deepStrictEqual(unpackRows(page, other).map((li) => li.getAttribute("data-archived")),
    ["true", "true", "true", "true", "false"], "the Done rows are not drawn read");
  const counted = () => card.children.find((node) => node.className === "side-card-open").getAttribute("aria-label");
  assert.match(counted(), /· 1 unread$/, `the card did not count the Dones: ${counted()}`);
  assert.ok(dones.took.every((ms) => ms < SHIFT_O_BUDGET_MS),
    `an e took over ${SHIFT_O_BUDGET_MS} ms: ${dones.took.map((ms) => ms.toFixed(1)).join(", ")}`);
  // z puts back the last, on the row drawn, and the card counts it.
  await pressHere(page, "z");
  assert.deepStrictEqual(page.restoreCalls.at(-1), { messages: ["9532104"] }, "z did not undo the last e");
  assert.equal(unpackedRow(page, "9532104").getAttribute("data-archived"), "false", "z did not draw the row unread");
  assert.match(counted(), /· 2 unread$/, `the card did not count the put back: ${counted()}`);

  // THE CONTROL: the list drawn anew on every pass, as before: the same presses build rows, so the
  // checks above can see it.
  const control = await shiftOPage(brokenScriptEach(
    ['const keep = sideCardsDrawn !== "" && sideCardsKept.whole === whole;', "const keep = false;"]));
  await mouseOnto(control, unpackedRow(control, "9532115"));
  const redrawn = await pressesInPlace(control, "O", { shiftKey: true }, 1, own);
  assert.ok(redrawn.built > 0 && !redrawn.kept, "the negative control did not draw the list again");
});

test("`#532 shift-o-latency`: a kept block is drawn again for what its rows show: a Done of a message read by a rule, an edit, a reaction", async () => {
  // From the adversarial review: a block kept from the last pass is drawn again only for what its parts
  // say. A noise message is read by a rule whether Done or not, so "still to do" alone did not change.
  const data = shiftOData();
  const noisy = "9532113";
  const page = newPage(new Map([[UNPACK_STORAGE, "on"]]));
  page.threadingSupported = true;
  data.messages = data.messages.map((one) => (one.id === noisy ? { ...one, noise: true } : one));
  page.threads = data.threads;
  page.messages = data.messages;
  forwardTimeline(page);
  await signIn(page);
  await showDiscord(page, data.messages);
  await pickThread(page, "threads");
  await page.settle();
  const row = unpackedRow(page, noisy);
  assert.equal(row.getAttribute("data-noise"), "true", "the premise: a message read by a rule");
  await mouseOnto(page, row);
  await pressHere(page, "e");
  assert.deepStrictEqual(page.dismissCalls.at(-1), { messages: [noisy] }, "the premise: e marked it Done");
  assert.equal(unpackedRow(page, noisy).getAttribute("data-archived"), "true", "the Done of a noise message was not drawn");
  assert.equal(unpackedRow(page, noisy).getAttribute("data-noise"), "false", "a Done noise row still says it is noise");

  // An edit and a reaction are in what a kept row is drawn again for, though its id and read state are
  // the same; and the thread's reported count and its cover, which decide its loading line.
  const look = page.pure("messageLook");
  const base = data.messages.find((one) => one.id === "9532112");
  assert.notEqual(look({ ...base, content: `${base.content} and more`, edited_timestamp: "2026-10-26T12:00:00Z" }), look(base),
    "an edit is not in a row's signature");
  assert.notEqual(look({ ...base, reactions: [{ emoji: "👍", count: 1, me: false }] }), look(base),
    "a reaction is not in a row's signature");
  const choice = (count) => ({ ...page.pure("threadChoices")().find((one) => one.id === "spaces/A/threads/s11"), count });
  const held = page.pure("unpackHeldMessages")(choice(SHIFT_O_REPLIES));
  assert.notEqual(page.pure("unpackSignature")(choice(SHIFT_O_REPLIES + 1), held),
    page.pure("unpackSignature")(choice(SHIFT_O_REPLIES), held), "a thread grown by its count keeps its block, unread");
});

