// --- `#523 voice-self-hearing` -------------------------------------------------------------------
//
// The owner, 2026-10-25: a new call said "Hello, let's connect you to your chat.", then heard "Let's
// connect you to your chat" as his and answered it. The phone's microphone hears its speaker. The
// greeting gate ended when the greeting was SENT, while seconds of it were still to play, and only for
// a session that promised one; the hosted agent's first message had no gate; and a transcript of the
// agent's own words was the owner's on screen, in the record and in what the server was told he said
// (`#511`). Times below: an answer of `seconds` starts after the 0.25 s lead, and is audible
// ECHO_TAIL_MS after its last sample.

const ECHO_TAIL_MS = sourceConstant("ECHO_TAIL_MS");
const ECHO_PARTIAL_GRACE_MS = sourceConstant("ECHO_PARTIAL_GRACE_MS");
const ECHO_GREETING_QUIET_MS = sourceConstant("ECHO_GREETING_QUIET_MS");
const GREETING = "Hello, let's connect you to your chat.";
const binaryFramesSent = (socket) => socket.sent.filter((frame) => typeof frame !== "string");
const shownTexts = (page) => session_lines(page).map((li) => li.text());
/** The rows not the assistant's that say `words`: a row's text starts with its speaker's label. */
const ownerRowsSaying = (page, words) =>
  shownTexts(page).filter((t) => !t.startsWith("assistant") && t.includes(words));
const MIC_HELD_FOR_AGENT = ["    if (micHeldForAgent()) {\n", "    if (false) {\n"];
const ECHO_NOT_JUDGED = ["  if (entry.nearAgent) judgeAgentEcho(entry, final);\n", ""];
/** Move the wall clock and the audio clock on together, as a phone's do. */
const advance = (page, ms) => {
  page.setClock(page.clock() + ms);
  page.audio.currentTime += ms / 1000;
};
/** When an answer of `seconds` that starts playing now stops being audible, from now. */
const audibleMs = (seconds) => 250 + seconds * 1000 + ECHO_TAIL_MS;
/** `seconds` of the assistant's voice on `vibe-talk-v1` (24 kHz). */
const v1Voice = (page, socket, seconds) => socket.onmessage({ data: page.pcmFrame(24000 * seconds, SPEECH) });
/** `seconds` of the assistant's voice on the hosted agent (16 kHz). */
const hostedVoice = (socket, seconds) =>
  hosted(socket, { type: "audio", audio_event: { audio_base_64: btoa("\u0000".repeat(32000 * seconds)) } });

/**
 * A `vibe-talk-v1` call past its opening: the owner spoke first, so the agent's answers may be
 * talked over, and echo cancellation is on (unless `applied` says the phone refused it).
 */
async function talkedV1Call(page, { applied } = {}) {
  if (applied !== undefined) page.appliedEchoCancellation = applied;
  const socket = await startNeutralCall(page);
  await page.settle();
  speech(socket, "user", 1, "What is new in the chat?", true);
  await page.settle();
  return socket;
}

/**
 * The agent answers `words` with `seconds` of voice, and the microphone sends a buffer `exposedAt`
 * ms into it (while it is audible, unless the microphone is held). The clock is left there.
 */
function answerHeard(page, socket, turn, words, seconds, exposedAt) {
  v1Voice(page, socket, seconds);
  speech(socket, "assistant", turn, words, true);
  advance(page, exposedAt);
  speakInto(page);
}

test("`#523 voice-self-hearing`: the microphone waits for a greeting to finish PLAYING, promised or not, and an answer after it can still be talked over", async () => {
  for (const greeting of [true, false]) {
    const run = async (script) => {
      const page = script ? newPage(new Map(), script) : newPage();
      const socket = await startNeutralCall(page, { greeting });
      await page.settle();
      v1Voice(page, socket, 3);
      speech(socket, "assistant", 1, GREETING, true);
      if (greeting) turnDone(socket, 1);
      await page.settle();
      page.expireTimers(sourceConstant("VOICE_CAPTURE_RESUME_MS"));
      advance(page, 1000);
      speakInto(page);
      const during = binaryFramesSent(socket).length;
      advance(page, audibleMs(3) - 1000 + (greeting ? 1 : ECHO_GREETING_QUIET_MS + 1));
      speakInto(page);
      return { page, socket, during, after: binaryFramesSent(socket).length };
    };
    const { page, socket, during, after } = await run();
    assert.equal(during, 0, `greeting ${greeting}: the microphone sent the greeting's own sound back while it played`);
    assert.equal(after, 1, `greeting ${greeting}: the microphone stayed shut after the greeting had played out`);
    // Echo cancellation is on: the owner talks over the next answer as he always could.
    v1Voice(page, socket, 2);
    advance(page, 500);
    speakInto(page);
    assert.equal(binaryFramesSent(socket).length, 2, `greeting ${greeting}: an answer after the greeting could not be talked over`);

    const control = await run(brokenScriptEach(MIC_HELD_FOR_AGENT));
    assert.equal(control.during, 1, "the control held the microphone too: this test cannot see the defect");
  }
});

test("`#523 voice-self-hearing`: an answer's words heard back are not the owner's — not drawn, filed or reported as heard — and his own words over it are", async () => {
  const ANSWER = "Hello, let's connect you to your chat. The coding agent says the build is green.";
  const run = async (script) => {
    const page = script ? newPage(new Map(), script) : newPage();
    const socket = await talkedV1Call(page);
    answerHeard(page, socket, 2, ANSWER, 4, 2000);
    // The recogniser's hypotheses of the speaker's sound, the incident's words, while it plays.
    speech(socket, "user", 3, "Let's", false);
    speech(socket, "user", 3, "Let's connect you", false);
    speech(socket, "user", 3, "Let's connect you to your chat.", true);
    await page.settle();
    return { page, socket };
  };
  const { page, socket } = await run();
  assert.deepEqual(ownerRowsSaying(page, "connect you"), [], "the agent's own words were drawn as the owner's");
  assert.ok(!page.heardPosts.some((post) => /connect/i.test(post.text)), "the agent's own words were reported as heard from the owner");
  // His own words, talked over the same answer, are his.
  speech(socket, "user", 4, "Stop, read me the last message instead.", true);
  turnDone(socket, 4);
  await page.settle();
  assert.deepEqual([...heardNow(page).values()].filter((t) => !t.startsWith("What is new")), ["Stop, read me the last message instead."]);
  assert.ok(!storedTexts(page).some((t) => /connect you/.test(t) && t.startsWith("you: ")), storedTexts(page).join(" | "));
  assert.match(page.el("connection-detail").textContent, /picked up the assistant's own words \("Let's connect you to your chat\."\)/);

  // THE CONTROL: a page that never judges a turn for the agent's echo reports and draws the incident's words.
  const control = await run(brokenScriptEach(ECHO_NOT_JUDGED));
  assert.ok(control.page.heardPosts.some((post) => /connect you to your chat/i.test(post.text)),
    "the control did not report the echo: this test cannot see the defect");
  assert.equal(ownerRowsSaying(control.page, "connect you").length, 1, "the control did not draw the echo as the owner's");
});

test("`#523 voice-self-hearing`: the owner answering in the agent's words just after it is his — a send ask, a yes, and anything when the microphone sent none of its sound", async () => {
  const QUESTION = "Should I send this to the coding agent?";
  const ASK = "Send this to the coding agent.";
  const cases = [
    // Begun after the grace for a partial: his send ask, word for word the question's.
    ["a send ask after the grace", {}, ASK, audibleMs(2) - 100, ECHO_PARTIAL_GRACE_MS + 100],
    // Inside the grace, but an answer to the question: the spoken yes judges it.
    ["a yes inside the grace", {}, "Go ahead and send it.", audibleMs(2) - 100, 300],
    // Half duplex: no buffer went while the agent was audible, so the service heard no echo.
    ["half duplex", { applied: false }, ASK, audibleMs(2) - 100, 200],
  ];
  for (const [what, options, said, exposedAt, after] of cases) {
    const page = newPage();
    const socket = await talkedV1Call(page, options);
    answerHeard(page, socket, 2, QUESTION, 2, exposedAt);
    advance(page, after);
    speech(socket, "user", 3, said.split(" ")[0], false);
    speech(socket, "user", 3, said, true);
    await page.settle();
    assert.ok([...heardNow(page).values()].includes(said), `${what}: the owner's words were not reported as heard`);
    assert.equal(ownerRowsSaying(page, said).length, 1, `${what}: the owner's words were not drawn as his`);
  }
});

test("`#523 voice-self-hearing`: a turn begun just after the agent fell silent reports nothing until it can be judged, so an echo's opening words never reach the server", async () => {
  const run = async (script) => {
    const page = script ? newPage(new Map(), script) : newPage();
    const socket = await talkedV1Call(page);
    answerHeard(page, socket, 2, "Shall I send it to the coding agent?", 2, audibleMs(2) - 100);
    advance(page, 300); // no longer audible, inside the grace
    speech(socket, "user", 3, "send it", false);
    await page.settle();
    const early = page.heardPosts.filter((post) => post.text === "send it").length;
    speech(socket, "user", 3, "send it to the coding agent", false);
    speech(socket, "user", 3, "send it to the coding agent", true);
    await page.settle();
    return { page, early };
  };
  const { page, early } = await run();
  assert.equal(early, 0, "the echo's first two words were reported as heard before the turn could be judged");
  assert.ok(!page.heardPosts.some((post) => post.text.startsWith("send it")), page.heardPosts.map((post) => post.text).join(" | "));
  assert.deepEqual(ownerRowsSaying(page, "send it"), [], "the echo was drawn as the owner's");
  const control = await run(brokenScriptEach(["    const owners = !spoken.entry.echo && !spoken.entry.undecided;\n",
    "    const owners = !spoken.entry.echo;\n"]));
  assert.equal(control.early, 1, "the control did not report the opening words: this test cannot see the defect");
});

test("`#523 voice-self-hearing`: on the hosted agent, the first message is not streamed back while it plays, a stall in it does not end it, and an answer's echo is not the owner's", async () => {
  const run = async (script) => {
    const page = script ? newPage(new Map(), script) : newPage();
    const socket = await startTalking(page);
    speakInto(page);
    const before = audioFrames(socket).length;
    hostedVoice(socket, 2);
    hostedSays(socket, GREETING);
    advance(page, 1000);
    speakInto(page);
    const during = audioFrames(socket).length - before;
    // The network stalls for a second and a half after the first part, then the rest arrives.
    advance(page, audibleMs(2) - 1000 + 1500);
    speakInto(page); // quiet: nothing to hear, so the microphone sends
    hostedVoice(socket, 1);
    advance(page, 300);
    speakInto(page);
    const afterStall = audioFrames(socket).length - before - during;
    return { page, socket, before, during, afterStall };
  };
  const { page, socket, before, during, afterStall } = await run();
  assert.equal(before, 1, "the microphone did not stream before the agent spoke");
  assert.equal(during, 0, "the first message's own sound was streamed back while it played");
  assert.equal(afterStall, 1, "the rest of the first message, after a stall, was streamed back while it played");
  advance(page, audibleMs(1) + ECHO_GREETING_QUIET_MS);
  speakInto(page);
  assert.equal(audioFrames(socket).length, 3, "the microphone stayed shut after the first message played out");

  // A later answer is talked over (echo cancellation is on), and its echo is not his.
  hostedVoice(socket, 3);
  hostedSays(socket, "The coding agent says the build is green and the deploy finished.");
  advance(page, 2500);
  speakInto(page);
  assert.equal(audioFrames(socket).length, 4, "an answer after the first message could not be talked over");
  advance(page, 1000);
  hostedHears(socket, "the build is green and the deploy finished");
  await page.settle();
  assert.ok(!page.heardPosts.some((post) => post.text.includes("build is green")), "an answer's echo was reported as heard");
  assert.deepEqual(ownerRowsSaying(page, "build is green"), [], "an answer's echo was drawn as the owner's");
  advance(page, 10000);
  hostedHears(socket, "Ask Claude whether the tests pass.");
  await page.settle();
  assert.deepEqual([...heardNow(page).values()], ["Ask Claude whether the tests pass."]);

  const control = await run(brokenScriptEach(MIC_HELD_FOR_AGENT));
  assert.equal(control.during, 1, "the control held the microphone too: this test cannot see the defect");
});

test("`#523 voice-self-hearing`: with echo cancellation refused, the microphone pauses whenever the agent is audible, and the call says so", async () => {
  const run = async (applied) => {
    const page = newPage();
    const socket = await talkedV1Call(page, { applied });
    const sent = binaryFramesSent(socket).length;
    v1Voice(page, socket, 2);
    advance(page, 1000);
    speakInto(page);
    const during = binaryFramesSent(socket).length - sent;
    advance(page, audibleMs(2) - 1000 + 1);
    speakInto(page);
    return { page, during, after: binaryFramesSent(socket).length - sent };
  };
  const refused = await run(false);
  assert.equal(refused.during, 0, "with nothing cancelling it, the agent's voice was streamed back while it played");
  assert.equal(refused.after, 1, "the microphone stayed shut after the agent fell silent");
  assert.match(refused.page.el("connection-detail").textContent, /echo cancellation is off for this call/);
  // THE CONTROL: applied, the owner talks over an answer, and nothing is said about it.
  const applied = await run(true);
  assert.equal(applied.during, 1, "with echo cancellation on, an answer could not be talked over");
  assert.doesNotMatch(applied.page.el("connection-detail").textContent, /echo cancellation is off/);
});

// --- a page running an older script than the server serves says so (#529 page-build-stale-notice) --------
//
// The owner, 2026-10-26, of a thread card drawn the old way: "Maybe I'm running a stale version". A page
// left open across a deploy keeps its old script; every timeline read now says which one the server serves.

test("`#529 page-build-stale-notice`: a read saying the server serves another page script shows New version — reload, which reloads only on a press", async () => {
  const page = newPage(new Map(), SCRIPT, (p) => { p.scriptSrc = "https://vibe.example/voice.js?v=aaaaaaaa11111111"; });
  const data = bigCardData();
  page.threadingSupported = true;
  page.threads = data.threads;
  page.messages = data.messages;
  const server = forwardTimeline(page);
  const answer = server.answer;
  let build = "aaaaaaaa11111111";
  server.answer = async (path) => {
    const response = await answer(path);
    return json(response.status, { ...JSON.parse(await response.text()), page_build: build });
  };
  await signIn(page);
  await showDiscord(page, data.messages);
  await page.settle();
  // The same build: nothing shown, and Settings names it.
  assert.equal(page.el("page-update").hidden, true, "the page offered a reload of the build it runs");
  assert.equal(page.el("settings-page-build").textContent, "This page is build aaaaaaaa.");
  // A deploy: the next read says another build.
  build = "bbbbbbbb22222222";
  await reReadChannel(page);
  assert.equal(page.el("page-update").hidden, false, "a page older than the server's did not say so");
  assert.match(page.el("page-update").textContent, /New version/);
  assert.match(page.el("settings-page-build").textContent, /build aaaaaaaa; the server now serves bbbbbbbb/);
  assert.equal(page.reloads || 0, 0, "the page reloaded by itself");
  await page.el("page-update").click();
  assert.equal(page.reloads, 1, "the chip did not reload the page");
  // A page that does not know its own build — loaded without a hashed address — never claims to be old.
  const unknown = newPage(new Map());
  unknown.threadingSupported = true;
  unknown.threads = data.threads;
  unknown.messages = data.messages;
  const other = forwardTimeline(unknown);
  const plain = other.answer;
  other.answer = async (path) => json(200, { ...JSON.parse(await (await plain(path)).text()), page_build: "cccccccc33333333" });
  await signIn(unknown);
  await showDiscord(unknown, data.messages);
  await unknown.settle();
  assert.equal(unknown.el("page-update").hidden, true, "a page with no build of its own offered a reload");
});

test("`#624 voice-page-modularity`: a page knows its build from the page build's hashed script name as it does from an older ?v= address, and from nothing else", () => {
  const buildOf = (src, script = SCRIPT) => newPage(new Map(), script, (p) => { p.scriptSrc = src; }).pure("PAGE_BUILD");
  const hash = "0123456789abcdef0123456789abcdef";
  assert.equal(buildOf(`https://vibe.example/assets/voice.${hash}.js`), hash);
  assert.equal(buildOf(`https://vibe.example/assets/voice.${hash}.js?x=1`), hash);
  assert.equal(buildOf("https://vibe.example/voice.js?v=aaaaaaaa11111111"), "aaaaaaaa11111111");
  for (const src of [`https://vibe.example/assets/voice.${hash.slice(1)}.js`, `https://vibe.example/assets/voice.${hash}0.js`,
    `https://vibe.example/assets/other.${hash}.js`, `https://vibe.example/assets/voice.${hash}.js.map`,
    `https://vibe.example/assets/voice.${hash.toUpperCase()}.js`, "https://vibe.example/voice.js"]) {
    assert.equal(buildOf(src), "", src);
  }
  // THE CONTROL: the reader as it was, ?v= alone, does not know a page loaded by the hashed name.
  const before = brokenScript("/\\/assets\\/voice\\.([0-9a-f]{32})\\.js(?:[?#]|$)/.exec(src) || ", "");
  assert.equal(buildOf(`https://vibe.example/assets/voice.${hash}.js`, before), "");
});

/**
 * `#521 server-side-search`. The search language's conformance corpus, which src/search_query.rs is
 * held to as well: the page's twin must fold, parse, match and plan upstream queries exactly as it
 * says. Values cross out of the page's realm through JSON, so a tree is compared as data.
 */
const SEARCH_CORPUS = JSON.parse(readFileSync(join(WEB, "..", "tests", "fixtures", "search_query.json"), "utf8"));

// The search language module and searchLanguage() are loaded near PRELUDE, above every test.

function searchCorpusDisagreements(language) {
  const fold = language.searchFold;
  const parse = language.searchQueryParse;
  const tree = language.searchQueryTree;
  const matches = language.searchQueryMatches;
  const subject = language.searchSubject;
  const plan = language.searchUpstreamPlan;
  const data = (value) => JSON.parse(JSON.stringify(value ?? null));
  const wrong = [];
  for (const { in: input, out } of SEARCH_CORPUS.fold) {
    if (fold(input) !== out) wrong.push(`fold ${JSON.stringify(input)} gave ${JSON.stringify(fold(input))}`);
  }
  for (const { query, tree: expected } of SEARCH_CORPUS.parse) {
    const got = data(tree(parse(query)));
    if (JSON.stringify(got) !== JSON.stringify(expected)) wrong.push(`parse ${JSON.stringify(query)} gave ${JSON.stringify(got)}`);
  }
  for (const { query, message, matches: expected, tz_offset_minutes: offset = 0 } of SEARCH_CORPUS.match) {
    const folded = subject({ author: message.author ?? "", authorId: message.author_id ?? "", text: message.text ?? "",
      links: message.links ?? [], createdMs: Date.parse(message.created), inThread: message.in_thread ?? false });
    const dayStart = (day) => Date.UTC(day.year, day.month - 1, day.day) - offset * 60_000;
    if (matches(parse(query), folded, dayStart) !== expected) wrong.push(`match ${JSON.stringify(query)} on ${JSON.stringify(message.text)}`);
  }
  for (const { query, queries, scan } of SEARCH_CORPUS.upstream) {
    const got = data(plan(parse(query)));
    if (JSON.stringify(got) !== JSON.stringify({ queries, scan })) wrong.push(`upstream ${JSON.stringify(query)} gave ${JSON.stringify(got)}`);
  }
  return wrong;
}

test("`#521 server-side-search`: the page's search language folds, parses, matches and plans exactly as the shared corpus says", () => {
  const counted = ["fold", "parse", "match", "upstream"].map((kind) => SEARCH_CORPUS[kind].length);
  assert.ok(counted.every((n) => n >= 20), `the corpus shrank: ${counted}`);
  assert.deepEqual(searchCorpusDisagreements(SEARCH_LANGUAGE), []);
  // `#624 voice-page-modularity`: the page runs the same functions, by the prelude, under the names
  // its legacy script has always called them by.
  const page = newPage();
  for (const name of ["searchQueryParse", "searchQueryTree", "searchQueryMatches", "searchSubject", "searchPositiveTerms"]) {
    assert.equal(page.pure(`typeof ${name}`), "function", name);
  }
  const node = page.pure("searchQueryParse")("from:Ada (a OR b) -c");
  assert.deepEqual(JSON.parse(JSON.stringify(page.pure("searchQueryTree")(node))),
    JSON.parse(JSON.stringify(SEARCH_LANGUAGE.searchQueryTree(SEARCH_LANGUAGE.searchQueryParse("from:Ada (a OR b) -c")))));
});

test("`#521 server-side-search`: the corpus catches a page that lost one fold entry or bound OR loosely (negative controls)", async () => {
  // Without final sigma folded, ΟΣ (lower-cased to ος) no longer finds ΟΣΑ (οσα).
  const LANGUAGE = "src/core/search/language.ts";
  const sigma = await searchLanguage([{ file: LANGUAGE, find: "[\"ς\", \"σ\"], ", replace: "" }]);
  assert.ok(searchCorpusDisagreements(sigma).some((line) => line.includes("ΟΔΟΣ")));
  // OR taking whatever follows it as a whole conjunction disagrees with Gmail's binding of its neighbours.
  const looseOr = await searchLanguage([{ file: LANGUAGE,
    find: "    while (tokens[at] === \"OR\") {\n      at += 1;\n      const node = unary();",
    replace: "    while (tokens[at] === \"OR\") {\n      at += 1;\n      const node = and(false);" }]);
  assert.ok(searchCorpusDisagreements(looseOr).some((line) => line.startsWith("parse \"a OR b c\"")));
});

// --- `#611 timeline-read-failures` -----------------------------------------------------------------

test("`#611 timeline-read-failures`: a channel read the server fails ends its loading line and says so", async () => {
  // The owner, 2026-10-27: "My vibe talk app is stuck. It is stuck loading messages." A view no read
  // has covered shows the loading line while its read is out; when the server fails that read, the
  // line goes and the failure is on screen, rather than "Loading threads…" standing.
  const page = await threadPage("main");
  page.timeline = errorResponse(502, "chat_error", "the chat service is limiting how fast it can be read");
  const pending = page.el("channel-view-threads").click();
  await page.settle();
  await pending;
  await page.settle();
  assert.equal(page.el("channel-loading").hidden, true, "the loading line outlived the failed read");
  const said = `${freshness(page).hidden ? "" : freshness(page).textContent} ${page.el("error").textContent}`;
  assert.match(said, /Refresh failed|could not|failed/i, `nothing on screen said the read failed: ${said}`);
});

test("`#611 timeline-read-failures`: a page the server answered from its own copy lands, and the pill says it could not refresh", async () => {
  const page = await threadPage("main");
  const standard = page.timeline;
  // Older than two minutes by the page's clock: `#617 cold-load-first-paint` keeps a younger copy quiet.
  const asOf = new Date(page.clock() - 5 * 60_000).toISOString();
  page.timeline = async (path, options) => {
    const response = await standard(path, options);
    const { delta: _delta, ...newest } = JSON.parse(await response.text());
    // The server's copy lags: it lacks the oldest message on screen.
    const messages = (newest.messages || []).slice(1);
    return json(200, { ...newest, messages, as_of: asOf,
      refresh_failed: "The chat service is limiting how fast it can be read." });
  };
  const before = shownIds(page);
  assert.ok(before.length > 1, "the premise is a list of rows");
  await reReadChannel(page);
  assert.deepStrictEqual(shownIds(page), before, "a row the server's copy lacks was taken off the screen");
  assert.equal(page.el("channel-loading").hidden, true);
  assert.equal(freshness(page).hidden, false);
  assert.equal(freshness(page).getAttribute("data-state"), "failed");
  assert.match(freshness(page).textContent, /^Refresh failed · showing messages from \d{2}:\d{2}$/);

  // The next read the service answers says the rows are current again: armed for three seconds
  // on, not the next poll (`#617 cold-load-first-paint`).
  page.timeline = standard;
  assert.ok(page.expireTimers(3000) > 0, "no soon read was armed");
  await page.settle();
  assert.equal(freshness(page).getAttribute("data-state"), "fresh");
});

// --- `#614 timeline-read-failures` -----------------------------------------------------------------

for (const failed of [true, false]) {
  test(`\`#614 timeline-read-failures\`: a thread list ${failed ? "from the server's own copy keeps" : "the provider answered takes away"} a card it lacks`, async () => {
    const page = await threadPage("main");
    await page.el("channel-view-threads").click();
    await page.settle();
    const standard = page.timeline;
    assert.match(page.el("thread-list").text(), /Second discussion/, "the premise is two cards");
    page.timeline = async (path, options) => {
      const response = await standard(path, options);
      if (new URL(path, "http://fixture.test").searchParams.get("view") !== "threads") return response;
      const { delta: _delta, ...newest } = JSON.parse(await response.text());
      const threads = (newest.threads || []).filter((thread) => thread.title !== "Second discussion");
      return json(200, { ...newest, threads, has_more: false, next_before: null,
        ...(failed ? { refresh_failed: "The chat service is limiting how fast it can be read." } : {}) });
    };
    await reReadChannel(page);
    assert.match(page.el("thread-list").text(), /First discussion/);
    if (failed) {
      assert.match(page.el("thread-list").text(), /Second discussion/, "a card the server's copy lacks was taken away");
    } else {
      assert.doesNotMatch(page.el("thread-list").text(), /Second discussion/, "the negative control: a full list removes");
    }
  });
}

// --- `#617 cold-load-first-paint` ------------------------------------------------------------------

/** Answer every channel read from the server's own copy, as of `ageMs` ago, until put back. */
function answeredFromCopy(page, ageMs) {
  const standard = page.timeline;
  const asOf = new Date(page.clock() - ageMs).toISOString();
  page.timeline = async (path, options) => {
    const response = await standard(path, options);
    const { delta: _delta, ...newest } = JSON.parse(await response.text());
    return json(200, { ...newest, as_of: asOf, refresh_failed: "The chat service did not answer in time." });
  };
  return standard;
}

test("`#617 cold-load-first-paint`: a page from the server's own copy a minute old says nothing failed", async () => {
  const page = await threadPage("main");
  answeredFromCopy(page, 60_000);
  await reReadChannel(page);
  assert.notEqual(freshness(page).getAttribute("data-state"), "failed");
  assert.doesNotMatch(freshness(page).textContent, /failed/i, freshness(page).textContent);
});

test("`#617 cold-load-first-paint`: after a page from the server's own copy the next read comes in seconds, not at the next poll", async () => {
  const page = await threadPage("main");
  const standard = answeredFromCopy(page, 5 * 60_000);
  await reReadChannel(page);
  assert.equal(freshness(page).getAttribute("data-state"), "failed");
  page.timeline = standard;
  const reads = page.timelineCalls.length;
  assert.ok(page.expireTimers(3000) > 0, "no read was armed within three seconds");
  await page.settle();
  assert.ok(page.timelineCalls.length > reads, "the soon read was not sent");
  assert.equal(freshness(page).getAttribute("data-state"), "fresh", freshness(page).textContent);
});

test("`#649 voice-agent-tools`: an answer's text that arrives after its turn_complete takes the place of 'no text received' and is filed as the agent's words", async () => {
  const page = newPage();
  const socket = await startNeutralCall(page);
  speech(socket, "user", 1, "summarize overnight", true);
  socket.onmessage({ data: secondOfSpeech(page) });
  turnDone(socket, 1);
  await page.settle();
  const noted = () => session_lines(page).filter((li) => li.getAttribute("data-no-text") === "");
  assert.equal(noted().length, 1);
  const rows = session_lines(page).length;
  // Seen live: the bridge's text for a turn came after that turn's turn_complete.
  speech(socket, "assistant", 1, "The runner came back at nine.", true);
  await page.settle();
  assert.equal(noted().length, 0, "the note stayed beside the words it said were missing");
  assert.equal(session_lines(page).length, rows, "the late text took a row of its own");
  assert.match(session_lines(page).at(-1).text(), /The runner came back at nine\.$/);
  // Filed once the next turn is under way, as the agent's.
  socket.onmessage({ data: secondOfSpeech(page) });
  speech(socket, "assistant", 2, "Anything else?", true);
  turnDone(socket, 2);
  await page.settle();
  assert.ok(storedTexts(page).includes("agent: The runner came back at nine."), storedTexts(page).join(" | "));
  assert.deepEqual(page.healthPosts.map((r) => r.cause), ["audio_without_text", "late_text"]);
});

test("`#649 voice-agent-tools`: Hang up while an answer is arriving listens a moment for its text, shows it in its row and files it", async () => {
  const page = newPage();
  const socket = await startNeutralCall(page);
  speech(socket, "user", 1, "what happened overnight", true);
  speech(socket, "assistant", 2, "Reading the messages.", true);
  socket.onmessage({ data: secondOfSpeech(page) });
  await page.el("hang-up").click();
  await page.settle();
  assert.equal(state(page), "ended");
  assert.notEqual(socket.readyState, 3, "closed before the answer's text could arrive");
  assert.ok(socket.sent.some((frame) => typeof frame === "string" && frame.includes('"quit"')), "no quit was sent");
  socket.onmessage({ data: JSON.stringify({ type: "transcript", role: "assistant", turn: 2, text: "Reading the messages. The build is green." }) });
  socket.onclose({ code: 1000, reason: "" });
  await page.settle();
  assert.equal(socket.readyState, 3);
  const shown = session_lines(page).filter((li) => li.text().includes("The build is green."));
  assert.equal(shown.length, 1, "the late text was not shown, or shown twice");
  assert.match(shown[0].text(), /Reading the messages\. The build is green\. \(text arrived after you hung up\)$/);
  assert.equal(
    session_lines(page).filter((li) => /Reading the messages\.( \(cut off\))?$/.test(li.text())).length,
    0,
    "the cut row stayed beside the whole answer"
  );
  await page.settle();
  assert.ok(
    storedTexts(page).includes("agent: Reading the messages. The build is green. (text arrived after you hung up)"),
    storedTexts(page).join(" | ")
  );
});

test("`#649 voice-agent-tools`: Hang up with no answer owed still closes the call's socket at once", async () => {
  const page = newPage();
  const socket = await startNeutralCall(page);
  speech(socket, "user", 1, "thanks", true);
  speech(socket, "assistant", 1, "You're welcome.", true);
  turnDone(socket, 1);
  await page.settle();
  await page.el("hang-up").click();
  assert.equal(socket.readyState, 3);
});

// --- `#650 cache-first-older-reads` ----------------------------------------------------------------

const COUNTS_SOON_MS = sourceConstant("COUNTS_SOON_MS");

/**
 * A channel of ten messages read on the timeline route, whose newest reads the server answers from its own
 * copy (`refresh_failed`), saying there is more (`stillMore`) as a server before `#650` did, or not, as one
 * that holds the view from its start does; a step back walks the provider and finds nothing older. The
 * reader at the top of the short list, where every redraw's scroll event asks for the step back. The reads
 * each of four polls made, as `reason:cursor`.
 */
async function pollsOverAShortCopy(stillMore) {
  const page = newPage();
  pagedTimeline(page, { steps: 1, size: 10 });
  await signIn(page);
  await showDiscord(page, []);
  const area = page.el("scroll-area");
  const standard = page.timeline;
  page.timeline = async (path, options) => {
    const url = new URL(path, "http://fixture.test");
    if (url.searchParams.get("before")) {
      return json(200, timelineAnswer({ view: url.searchParams.get("view"), messages: [], limit: 10,
        has_threads: true, has_more: false, next_before: null }));
    }
    const { delta: _delta, ...newest } = JSON.parse(await (await standard(path, options)).text());
    return json(200, { ...newest, has_more: stillMore, next_before: stillMore ? "vt-served.x" : null,
      as_of: new Date(page.clock() - 1000).toISOString(),
      refresh_failed: "Answered from this server's copy while the chat service is read." });
  };
  const polls = [];
  for (let i = 0; i < 4; i += 1) {
    const before = page.timelineCalls.length;
    // The poll, and the soon reads after a page from the copy (`#617 cold-load-first-paint`).
    for (const due of [DISCORD_POLL_MS, 3000, 10000]) {
      page.expireTimers(due);
      await page.settle();
      // A redraw in a real browser scrolls the list, and the reader is at its top.
      area.scrollTop = 0;
      await area.dispatch("scroll");
      await page.settle();
    }
    polls.push(page.timelineCalls.slice(before).map((call) => {
      const url = new URL(call, "http://fixture.test");
      return `${url.searchParams.get("reason")}:${url.searchParams.get("before") ? "before" : "newest"}`;
    }));
  }
  return polls;
}

test("`#650 cache-first-older-reads`: a short view the server's copy holds from its start is never stepped back from at the next poll", async () => {
  // Live after `#622`: one open page read a step back every forty-five seconds, each walking Slack for
  // 2.6 s to learn there was nothing older. The copy said there was more; the page at the top of its
  // short list stepped back after every poll's redraw, learned there was nothing, and the next poll's
  // copy said there was more again. A copy that says there is nothing older is believed.
  const polls = await pollsOverAShortCopy(false);
  assert.ok(polls.every((reads) => reads.length > 0 && reads.every((read) => read.endsWith(":newest"))),
    `a poll stepped back: ${JSON.stringify(polls)}`);

  // THE CONTROL, the server as it was: a step back after every poll.
  const control = await pollsOverAShortCopy(true);
  assert.ok(control.every((reads) => reads.includes("older:before")), JSON.stringify(control));
});

/**
 * Main with a root whose count outruns the store, so each read of Main past the interval reads All behind
 * it for its counts; the server answers those from its own copy while `fromCopy()` says so. The counts
 * reads it made, by the time of each.
 */
async function countsFromCopy(script, fromCopy) {
  const { page, server, held, quietReply } = await heldAllReads(script);
  const serve = page.timeline;
  const counted = [];
  page.timeline = async (path, options) => {
    const url = new URL(path, "http://fixture.test");
    if (url.searchParams.get("reason") !== "counts") return serve(path, options);
    counted.push(page.clock());
    const answer = server.answer(path);
    const body = JSON.parse(await (await answer).text());
    if (!fromCopy()) return json(200, body);
    // The copy says nothing of the second discussion: it leaves the counts outrunning what the page holds.
    const messages = (body.messages || []).filter((m) => !["203", "204", "250"].includes(String(m.id)));
    return json(200, { ...body, messages,
      refresh_failed: "Answered from this server's copy while the chat service is read." });
  };
  void held;
  page.setClock(page.clock() + COUNTS_ALL_READ_MS + 1000);
  quietReply();
  await pollOnce(page);
  for (let i = 0; i < 3; i += 1) await page.settle();
  return { page, counted };
}

test("`#650 cache-first-older-reads`: a counts read the server answered from its copy that leaves the counts outrunning is asked once more soon, and one it trusts ends the asking", async () => {
  let copy = true;
  const { page, counted } = await countsFromCopy(SCRIPT, () => copy);
  assert.equal(counted.length, 1, "fixture: All was not read for Main's counts");
  // The read the server made behind that answer has landed by the next one.
  copy = false;
  assert.ok(page.expireTimers(COUNTS_SOON_MS) > 0, "no soon counts read was armed");
  for (let i = 0; i < 3; i += 1) await page.settle();
  assert.equal(counted.length, 2, "the counts were not asked again soon");
  page.expireTimers(COUNTS_SOON_MS);
  for (let i = 0; i < 3; i += 1) await page.settle();
  page.setClock(page.clock() + DISCORD_POLL_MS);
  await pollOnce(page);
  for (let i = 0; i < 3; i += 1) await page.settle();
  assert.equal(counted.length, 2, "a counts read the page trusts did not end the asking");

  // THE CONTROL, the page as it was: one counts read, then nothing for five minutes.
  const control = await countsFromCopy(brokenScript(
    "    else if (!soon) setTimeout(() => void readAllForCounts(channel, true).catch(() => {}), COUNTS_SOON_MS);\n", ""),
  () => true);
  control.page.expireTimers(COUNTS_SOON_MS);
  for (let i = 0; i < 3; i += 1) await control.page.settle();
  assert.equal(control.counted.length, 1, JSON.stringify(control.counted));
});

// The owner, 2026-10-29 (#624 voice-page-modularity): replies seen in Slack to a message posted moments
// earlier, not seen here. Every way they may come in, by stream with the thread record, by stream
// without one (left unplaced until a read places it), or by the poll's read alone, puts each reply in
// All and counts it on the root's Thread(N) in Main.
for (const how of ["stream", "bare-stream", "poll-only"]) {
  test(`replies (${how}) to a message that arrived live moments earlier are in All and counted on Main`, async () => {
    const { page } = await freshMessagePage();
    await pickThread(page, "flat");
    const thread = { id: "spaces/A/threads/live", root_message_id: "300", is_root: true, reply_count: 0, reply_count_exact: true };
    const root = message({ id: "300", content: "the owner's new question", author: "owner", author_id: "1000000000000000099",
      author_is_bot: false, thread });
    page.messages = [...page.messages, root];
    await deliver(page, page.stream(), sseMessage(root));
    await page.settle();
    for (const n of [1, 2, 3]) {
      page.setClock(page.clock() + 27000);
      const reply = message({ id: `30${n}`, content: `answer ${n}`, author: "bot", author_id: "1000000000000000088", author_is_bot: true,
        thread: { ...thread, is_root: false, reply_count: null, reply_count_exact: false } });
      page.messages = [...page.messages.map((m) => (m.id === "300" ? { ...m, thread: { ...thread, reply_count: n } } : m)), reply];
      if (how === "stream") await deliver(page, page.stream(), sseMessage(reply));
      if (how === "bare-stream") {
        const { thread: _thread, ...bare } = reply;
        await deliver(page, page.stream(), sseMessage(bare));
      }
      for (let i = 0; i < 3; i += 1) await page.settle();
    }
    page.setClock(page.clock() + DISCORD_POLL_MS);
    await pollOnce(page);
    for (let i = 0; i < 3; i += 1) await page.settle();
    assert.deepStrictEqual(shownIds(page).filter((id) => id.startsWith("30")), ["300", "301", "302", "303"], `${how}: All lost a reply`);
    await pickThread(page, "main");
    assert.ok(!shownIds(page).includes("301"), `${how}: a reply was drawn on Main`);
    assert.equal(tagOf(rowOf(page, "300")).text, "Thread(3)", `${how}: Main's root does not count its replies`);
  });
}
